// Lektionen 91–102 (Offenbarungsreihenfolge, Kairoer Chronologie) – medinensische Phase
window.LEKTIONEN12 = [
// ───────────────────────── Lektion 91: Al-Mumtaḥana ─────────────────────────
{
sure: 60, offb: 91, name: "Al-Mumtaḥana", arab: "سُورَةُ الْمُمْتَحَنَةِ", de: "Die Geprüfte", verse: 13, ort: "Medina",
zeit: "Medina, zwischen dem Vertrag von Ḥudaibiya (6 n. H.) und der Eroberung Mekkas (8 n. H.) – Anlass ist ein abgefangener Brief",
kurz: "Eine Sure über Loyalität – und über ihre Grenzen. Sie beginnt mit einem echten Spionagefall: Ḥāṭib ibn Abī Baltaʿa, ein Badr-Kämpfer, schrieb heimlich an die Quraisch, um seine Familie in Mekka zu schützen. Der Brief wurde abgefangen. Der Prophet ﷺ fragte nach seinem Motiv, nahm seine Erklärung an und verzieh ihm – aber Allah sandte die Regel herab: Nehmt nicht die zu Verbündeten, die euch wegen eures Glaubens bekriegen und vertreiben. Als Vorbild nennt die Sure Ibrāhīm und seine Gefährten. Und dann folgt der Satz, der die ganze Frage ‚Muslime und Nichtmuslime‘ ordnet: Allah verbietet euch nicht, gütig und gerecht zu denen zu sein, die euch nicht bekämpft und nicht vertrieben haben (60:8). Zum Schluss: die Prüfung der auswandernden Frauen (daher der Name) und ihr eigener Treueschwur.",
schluessel: {arab: "لَّا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَارِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ", ueb: "Allah verbietet euch nicht, gegenüber denen, die euch nicht der Religion wegen bekämpft und euch nicht aus euren Häusern vertrieben haben, gütig zu sein und sie gerecht zu behandeln.", ref: "60:8"},
kontext: ["Die Lage: Der Vertrag von Ḥudaibiya war von Verbündeten der Quraisch gebrochen worden, und der Prophet ﷺ bereitete im Stillen den Zug nach Mekka vor. Ḥāṭib ibn Abī Baltaʿa hatte in Mekka Familie, aber keinen Stamm, der sie schützte. Er schrieb den Quraisch eine Warnung – nicht aus Unglauben, wie er selbst sagte, sondern um sich bei ihnen einen ‚Gefallen‘ zu sichern. Der Prophet ﷺ schickte ʿAlī, az-Zubair und al-Miqdād los; sie holten den Brief bei einer Frau auf dem Weg nach Mekka heraus (Sahih al-Buchari, Nr. 3007; Sahih Muslim, Nr. 2494).",
"Was dann geschah, ist eine Lektion in Gerechtigkeit: ʿUmar wollte Ḥāṭib als Heuchler hinrichten lassen. Der Prophet ﷺ sagte: „Er hat an Badr teilgenommen – und was weißt du, vielleicht hat Allah auf die Badr-Leute geschaut und gesagt: Tut, was ihr wollt, Ich habe euch vergeben.“ Ein schwerer Fehler eines guten Menschen wurde nicht mit seiner ganzen Biografie gleichgesetzt. Aber die Regel kam trotzdem: Loyalität gegenüber einer Kriegspartei, die den Islam vernichten will, ist nicht verhandelbar.",
"Wichtig für dich und für jedes Gespräch: Dieselbe Sure, die die Allianz mit aktiven Feinden verbietet, gebietet in Vers 8 Güte (birr) und Gerechtigkeit (qisṭ) gegenüber allen Friedlichen – siehe ausführlich im Modul Brennpunkt-Verse (60:8–9). Der Anlass von 60:8 ist rührend menschlich: Asmāʾ bint Abī Bakr fragte, ob sie ihre nichtmuslimische Mutter empfangen dürfe – „Ja, pflege die Bindung zu deiner Mutter“ (Sahih al-Buchari, Nr. 2620; Sahih Muslim, Nr. 1003)."],
asbab: [
 {text: "Verse 1–3: der Brief des Ḥāṭib ibn Abī Baltaʿa an die Quraisch, das Abfangen und die Entscheidung des Propheten ﷺ.", quelle: "Sahih al-Buchari, Nr. 3007; Sahih Muslim, Nr. 2494"},
 {text: "Verse 8–9: Asmāʾ bint Abī Bakr und ihre nichtmuslimische Mutter.", quelle: "Sahih al-Buchari, Nr. 2620; Sahih Muslim, Nr. 1003"},
 {text: "Verse 10–12: Nach Ḥudaibiya kamen gläubige Frauen aus Mekka nach Medina; sie wurden geprüft (imtiḥān), ob ihr Glaube echt war. ʿĀʾischa berichtet, dass der Prophet ﷺ sie mit Vers 12 prüfte und dass seine Hand beim Treueschwur niemals die Hand einer Frau berührte – er nahm ihn mit Worten ab.", quelle: "Sahih al-Buchari, Nr. 4891; Sahih Muslim, Nr. 1866"}
],
begriffe: [
 {arab: "أَوْلِيَاء", tr: "auliyāʾ", wurzel: "w-l-y", erkl: "Verbündete, Schutzherren, enge Loyalitätspartner. Verboten ist die walāya mit denen, die den Islam bekämpfen – nicht Freundlichkeit, Nachbarschaft oder Handel (vgl. Brennpunkt 5:51)."},
 {arab: "أُسْوَة حَسَنَة", tr: "uswa ḥasana", wurzel: "ʾ-s-w", erkl: "„Schönes Vorbild“ (60:4) – Ibrāhīm und seine Gefährten, die sich klar vom Götzendienst ihres Volkes lossagten. Dieselbe Formel benutzt 33:21 für den Propheten ﷺ."},
 {arab: "تَبَرُّوهُمْ", tr: "tabarrūhum", wurzel: "b-r-r", erkl: "„Dass ihr gütig zu ihnen seid“ – von birr, dem stärksten Wohltatswort, das auch für die Pflicht gegenüber den Eltern steht (birr al-wālidain). Der Koran sagt nicht nur ‚duldet sie‘, sondern ‚seid gut zu ihnen‘."},
 {arab: "تُقْسِطُوا", tr: "tuqsiṭū", wurzel: "q-s-ṭ", erkl: "„Dass ihr gerecht zu ihnen seid“ – qisṭ ist Gerechtigkeit, die jedem sein Recht gibt. „Allah liebt die Gerechten (al-muqsiṭīn)“ (60:8)."},
 {arab: "فَامْتَحِنُوهُنَّ", tr: "fa-mtaḥinūhunna", wurzel: "m-ḥ-n", erkl: "„So prüft sie“ (60:10) – die Prüfung der Auswanderinnen, ob sie um des Glaubens willen kamen. Daher der Name der Sure: die Geprüfte. „Allah weiß besser um ihren Glauben“ – Menschen prüfen das Äußere, das Innere kennt nur Er."},
 {arab: "بَيْعَة", tr: "baiʿa", wurzel: "b-y-ʿ", erkl: "Treueschwur – wörtlich ein ‚Handel‘ mit Allah (vgl. 9:111). Der Frauen-Schwur in 60:12 enthält sechs Punkte: kein Schirk, kein Diebstahl, keine Unzucht, keine Kindstötung, keine Verleumdung, kein Ungehorsam im Guten."}
],
tafsir: [
 {vers: "Verse 1–3: der Fall Ḥāṭib", text: "„O ihr, die ihr glaubt, nehmt nicht Meinen Feind und euren Feind zu Schutzherren, indem ihr ihnen Zuneigung entgegenbringt – wo sie doch das verleugnen, was von der Wahrheit zu euch gekommen ist, und den Gesandten und euch vertreiben, weil ihr an Allah glaubt.“ – Ibn Kathīr betont die Begründung im Vers selbst: Es geht um eine Partei, die vertreibt und bekämpft. Vers 3 nimmt Ḥāṭibs Motiv ernst und widerlegt es: „Weder eure Verwandtschaft noch eure Kinder werden euch am Tag der Auferstehung nützen“ (vgl. Lektion 6 und 24: Verwandtschaft rettet nicht). Lehre für heute: Sorge um die Familie ist legitim, aber sie rechtfertigt keinen Verrat an der Wahrheit."},
 {vers: "Verse 4–7: das Vorbild Ibrāhīm", text: "Ibrāhīm und seine Leute sagten ihrem Volk: „Wir sagen uns von euch und dem los, was ihr anbetet … bis ihr an Allah allein glaubt.“ – mit einer ausdrücklichen Ausnahme: Ibrāhīms Bitte um Vergebung für seinen Vater ist KEIN Vorbild (60:4), denn er tat es aufgrund eines Versprechens. Dann das Gebet: „Unser Herr, mache uns nicht zur Versuchung (fitna) für die Ungläubigen“ – d. h. lass sie nicht durch unser schlechtes Verhalten vom Islam abgestoßen werden. Und Vers 7 öffnet die Tür: „Vielleicht wird Allah zwischen euch und denen, mit denen ihr verfeindet seid, Zuneigung stiften.“ As-Saʿdī: Genau das geschah – nach der Eroberung Mekkas wurden viele der früheren Feinde Brüder im Glauben."},
 {vers: "Verse 8–9: die Generalregel", text: "Die zwei Verse, die du in jedem Gespräch über ‚Islam und Nichtmuslime‘ zuerst nennen solltest: Güte und Gerechtigkeit gegenüber allen, die nicht wegen der Religion kämpfen und nicht vertreiben; nur die Allianz mit aktiven Verfolgern ist verboten. Der Koran teilt Menschen hier nicht nach Bekenntnis, sondern nach Verhalten. Ausführlich mit Hukm und Gesprächsanleitung: Brennpunkt-Modul, Gruppe ‚Verhältnis zu Nichtmuslimen‘."},
 {vers: "Verse 10–13: die Auswanderinnen und ihr Schwur", text: "Nach Ḥudaibiya mussten Männer, die aus Mekka flohen, zurückgeschickt werden – Frauen aber nicht: „Wenn ihr wisst, dass sie gläubig sind, dann schickt sie nicht zu den Ungläubigen zurück. Sie sind ihnen nicht erlaubt, und sie sind ihnen nicht erlaubt.“ Die Ehe zwischen einer Muslimin und einem Nichtmuslim wird aufgelöst; den früheren Ehemännern wird ihre Brautgabe erstattet – selbst im Konflikt bleibt der Koran finanziell gerecht. Vers 12 enthält den Treueschwur der Frauen – Frauen schworen dem Propheten ﷺ selbstständig, als eigene Rechtspersonen, nicht über ihre Männer. Der Schlussvers wiederholt die Warnung von Vers 1 und schließt den Rahmen."}
],
ahadith: [
 {text: "Der Bericht über Ḥāṭibs Brief – „Was hat dich dazu gebracht?“ – „Ich bin nicht ungläubig geworden … ich wollte bei ihnen eine Hand haben, mit der Allah meine Familie schützt.“ – „Er hat euch die Wahrheit gesagt.“", quelle: "Sahih al-Buchari, Nr. 3007; Sahih Muslim, Nr. 2494"},
 {text: "Asmāʾ: „Meine Mutter kam zu mir, und sie war Götzendienerin … soll ich die Bindung zu ihr pflegen?“ – „Ja, pflege die Bindung zu deiner Mutter.“", quelle: "Sahih al-Buchari, Nr. 2620; Sahih Muslim, Nr. 1003"},
 {text: "ʿĀʾischa: Der Prophet ﷺ prüfte die gläubigen Frauen mit diesem Vers (60:12); „bei Allah, seine Hand berührte niemals die Hand einer Frau beim Treueschwur – er nahm ihn nur mit Worten ab“.", quelle: "Sahih al-Buchari, Nr. 4891; Sahih Muslim, Nr. 1866"}
],
hanafi: "Zu 60:10 (Auflösung der Ehe bei Glaubensverschiedenheit): Konsens aller Schulen ist, dass eine Muslimin keinen nichtmuslimischen Mann heiraten darf. Hanafitische Besonderheit beim Fall, dass eine Ehefrau den Islam annimmt und ihr Mann nicht: Lebt das Paar unter islamischer Rechtsordnung, wird dem Mann der Islam angeboten; lehnt er ab, trennt der Richter die Ehe (tafrīq). Außerhalb davon gilt die Ehe nach der Schule als aufgelöst, sobald drei Menstruationen der Frau verstrichen sind. In heutigen Einzelfällen: unbedingt einen qualifizierten Gelehrten fragen – hier geht es um Familien, nicht um Theorie.",
umsetzung: [
 "Lerne 60:8 auswendig und nutze ihn als Grundsatz für deinen Umgang mit nichtmuslimischen Nachbarn, Kollegen und Verwandten: aktiv gütig (birr) und gerecht (qisṭ) – das ist Gebot, nicht nur Erlaubnis.",
 "Lerne aus dem Fall Ḥāṭib, gerecht zu urteilen: Ein schwerer Fehler eines Menschen löscht nicht sein ganzes Gutes aus. Bevor du jemanden abschreibst, frag nach seinem Motiv – so wie der Prophet ﷺ fragte.",
 "Bete das Gebet aus 60:5: „Unser Herr, mache uns nicht zur Versuchung für die Ungläubigen“ – und prüfe dein Verhalten: Zieht es Menschen zum Islam hin oder stößt es sie ab?",
 "Pflege die Bindung zu nichtmuslimischen Verwandten – besonders zu Eltern – so wie Asmāʾ es auf Anweisung des Propheten ﷺ tat."
]
},

// ───────────────────────── Lektion 92: An-Nisāʾ ─────────────────────────
{
sure: 4, offb: 92, name: "An-Nisāʾ", arab: "سُورَةُ النِّسَاءِ", de: "Die Frauen", verse: 176, ort: "Medina",
zeit: "Medina, großteils nach der Schlacht von Uḥud (3 n. H.), als viele Familien ihre Versorger verloren hatten; der Schlussvers gehört zu den letzten Offenbarungen",
kurz: "Die große Sure der Gerechtigkeit für die Schwachen. Nach Uḥud standen in Medina Dutzende Witwen und Waisen ohne Versorger da – und in der alten arabischen Ordnung erbten Frauen und Kinder nichts, sie wurden selbst vererbt. An-Nisāʾ ordnet das neu: Schutz des Waisenvermögens, festes Erbrecht für Frauen und Töchter, die Brautgabe als Eigentum der Frau, Regeln für Ehe, Streit und Versöhnung. Dann weitet sie den Blick: Gerechtigkeit vor Gericht, Treuhand gegenüber Herrschern, das Gebet in Gefahr, der Umgang mit Heuchlern und mit den Schriftbesitzern. Sie beginnt mit einem Vers über die eine Menschheitsfamilie („erschaffen aus einem einzigen Wesen“) und endet mit Erbrecht – vom Ursprung des Menschen bis zu seinem Nachlass. Mehrere der heute meistdiskutierten Verse stehen hier (4:3, 4:11, 4:34, 4:89) – du findest sie ausführlich im Brennpunkt-Modul.",
schluessel: {arab: "يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ وَاحِدَةٍ", ueb: "O ihr Menschen, fürchtet euren Herrn, Der euch aus einem einzigen Wesen erschaffen hat.", ref: "4:1"},
kontext: ["Uḥud (3 n. H.) war ein Einschnitt: rund siebzig Gefallene, und in fast jeder Familie Medinas fehlte plötzlich ein Mann. Die Witwe des gefallenen Saʿd ibn ar-Rabīʿ kam mit ihren zwei Töchtern zum Propheten ﷺ: Der Onkel der Mädchen hatte das gesamte Vermögen an sich genommen. Daraufhin wurden die Erbverse herabgesandt (Sunan Abū Dāwūd, Nr. 2891; Sunan at-Tirmidhī, Nr. 2092). Das ist der Grundton der ganzen Sure: Recht als Schutz der Schwachen gegen die Starken.",
"Die Sure entstand über einen längeren Zeitraum: Ihr Kern gehört in die Jahre nach Uḥud, einzelne Teile (Gebet in Gefahr, Heuchler, Schriftbesitzer) in die folgenden Jahre, und der letzte Vers über die Erbschaft ohne Eltern und Kinder (kalāla) gehört nach al-Barāʾ zu den allerletzten Versen, die herabkamen (Sahih al-Buchari, Nr. 4605; Sahih Muslim, Nr. 1618).",
"Als Ibn Masʿūd dem Propheten ﷺ auf dessen Bitte aus dieser Sure vortrug und zu Vers 41 kam – „Wie wird es dann sein, wenn Wir aus jeder Gemeinschaft einen Zeugen bringen und dich als Zeugen gegen diese bringen?“ – sagte der Prophet ﷺ: „Genug jetzt.“ Ibn Masʿūd schaute auf: Seine Augen flossen über vor Tränen (Sahih al-Buchari, Nr. 5050; Sahih Muslim, Nr. 800). Eine Sure voller Gesetze – und mittendrin ein Vers, der den Propheten ﷺ weinen ließ."],
asbab: [
 {text: "4:11–12 (Erbverse): Die Witwe des Saʿd ibn ar-Rabīʿ und ihre Töchter, denen der Onkel das Erbe genommen hatte.", quelle: "Sunan Abū Dāwūd, Nr. 2891; Sunan at-Tirmidhī, Nr. 2092"},
 {text: "4:3: ʿĀʾischa erklärt, dass Vormünder vermögende Waisenmädchen heiraten wollten, ohne ihnen eine gerechte Brautgabe zu geben – der Vers verbot das.", quelle: "Sahih al-Buchari, Nr. 4574"},
 {text: "4:59 („Gehorcht Allah und dem Gesandten und denen unter euch, die Befehlsgewalt haben“): nach Ibn ʿAbbās über ʿAbdullāh ibn Ḥudhāfa, einen Truppenführer.", quelle: "Sahih al-Buchari, Nr. 4584; Sahih Muslim, Nr. 1834"},
 {text: "4:65: der Wasserstreit zwischen az-Zubair und einem Anṣārī, der das Urteil des Propheten ﷺ nicht annehmen wollte.", quelle: "Sahih al-Buchari, Nr. 2359–2360; Sahih Muslim, Nr. 2357"},
 {text: "4:95 („Nicht gleich sind die Daheimbleibenden … außer denen mit Gebrechen“): Der blinde Ibn Umm Maktūm fragte nach seiner Lage – daraufhin kam die Ausnahme ‚außer denen mit Gebrechen‘ herab (vgl. Lektion 24).", quelle: "Sahih al-Buchari, Nr. 4592; Sahih Muslim, Nr. 1898"},
 {text: "4:176: nach al-Barāʾ der letzte herabgesandte Vers (über die kalāla).", quelle: "Sahih al-Buchari, Nr. 4605; Sahih Muslim, Nr. 1618"}
],
begriffe: [
 {arab: "نَفْس وَاحِدَة", tr: "nafs wāḥida", wurzel: "n-f-s", erkl: "„Ein einziges Wesen“ (4:1) – Ādam als gemeinsamer Ursprung. Daraus folgt: Kein Volk, keine Hautfarbe, kein Geschlecht steht von Natur aus über dem anderen; alle Rechte der Sure ruhen auf dieser einen Menschheitsfamilie."},
 {arab: "الْأَرْحَام", tr: "al-arḥām", wurzel: "r-ḥ-m", erkl: "„Die Verwandtschaftsbande“ (4:1) – wörtlich die Mutterschöße, von derselben Wurzel wie raḥma (Barmherzigkeit). Allah nennt sie direkt neben Sich selbst: „Fürchtet Allah … und (achtet) die Verwandtschaftsbande.“"},
 {arab: "صَدُقَات", tr: "ṣaduqāt", wurzel: "ṣ-d-q", erkl: "Die Brautgaben (4:4) – von ṣidq, Wahrhaftigkeit: Die Brautgabe ist der Beweis, dass der Mann es ernst meint. Sie gehört allein der Frau, „als freiwillige Gabe“ – weder Vater noch Bruder dürfen sie nehmen."},
 {arab: "فَرِيضَة", tr: "farīḍa", wurzel: "f-r-ḍ", erkl: "„Festgelegter Anteil / Pflicht von Allah“ (4:11). Davon kommt ʿilm al-farāʾiḍ, die islamische Erbrechtswissenschaft. Die Erbanteile sind nicht menschliche Verhandlungssache, sondern göttliche Festlegung."},
 {arab: "قَوَّامُون", tr: "qawwāmūn", wurzel: "q-w-m", erkl: "„Die für etwas einstehen, Verantwortung tragen“ (4:34) – die Versorgungs- und Schutzpflicht des Mannes. Ausführlich mit allen Bedingungen im Brennpunkt-Modul (4:34)."},
 {arab: "تَيَمُّم", tr: "tayammum", wurzel: "y-m-m", erkl: "„Sich (dem reinen Boden) zuwenden“ (4:43) – die Ersatzwaschung mit reiner Erde, wenn Wasser fehlt oder schadet. Ein Geschenk an diese Umma: Das Gebet scheitert nie am fehlenden Wasser."},
 {arab: "كَلَالَة", tr: "kalāla", wurzel: "k-l-l", erkl: "Ein Verstorbener ohne Eltern und Kinder (4:12, 4:176). Selbst ʿUmar fand diese Frage schwer und fragte den Propheten ﷺ mehrmals – das letzte Wort der Sure klärt sie."}
],
tafsir: [
 {vers: "Verse 1–14: Familie, Waisen, Erbe", text: "Die Sure beginnt bei der Menschheit und landet sofort bei den Schwächsten: „Gebt den Waisen ihr Vermögen und tauscht nicht Schlechtes gegen Gutes“ (4:2). Wer Waisenvermögen verschlingt, „verschlingt Feuer in seinen Bauch“ (4:10). Vers 3 regelt die Ehe mit bis zu vier Frauen unter strikter Gerechtigkeitsbedingung – „wenn ihr fürchtet, nicht gerecht zu sein, dann nur eine“ (ausführlich im Brennpunkt 4:3). Vers 4 macht die Brautgabe zum Eigentum der Frau. Dann die Erbverse 11–12: Töchter, Söhne, Eltern, Ehepartner, Geschwister bekommen feste Anteile – revolutionär in einer Welt, in der Frauen nichts erbten. Das Verhältnis 2:1 zwischen Sohn und Tochter steht in einem Gesamtsystem, in dem der Mann die Unterhaltspflicht trägt (ausführlich im Brennpunkt 4:11). Die Verse 13–14 nennen diese Regeln ḥudūd Allāh – Grenzen Allahs: Wer sie einhält, betritt Gärten; wer sie überschreitet, erwartet Feuer."},
 {vers: "Verse 15–35: Ehe, verbotene Verbindungen, Streit und Versöhnung", text: "Vers 19 schafft die alte Praxis ab, Frauen wie Erbmasse zu ‚übernehmen‘, und gibt den Grundbefehl der Ehe: „Lebt mit ihnen auf rechtliche Weise (bi-l-maʿrūf). Wenn ihr sie nicht mögt – vielleicht mögt ihr etwas nicht, in das Allah viel Gutes legt.“ Die Verse 22–24 zählen die verbotenen Eheverbindungen auf (Mütter, Töchter, Schwestern, Milchverwandte u. a.). Vers 28: „Allah will euch Erleichterung verschaffen, denn der Mensch wurde schwach erschaffen.“ Vers 31 verspricht: Wer die großen Sünden meidet, dem werden die kleinen getilgt (dazu der Hadith der sieben verderblichen Sünden: Sahih al-Buchari, Nr. 2766; Sahih Muslim, Nr. 89). Vers 32 verbietet den Neid auf das, was Allah anderen gegeben hat – Männern wie Frauen gehört, was sie erworben haben. Die Verse 34–35 regeln die Verantwortung des Mannes und das Verfahren bei schwerem Ehestreit – Ermahnung, Distanz, und bei Zerrüttung Schiedsleute aus beiden Familien. Den dritten Schritt von 4:34 hat die Sunna extrem eingegrenzt; der Prophet ﷺ selbst schlug nie eine Frau (Sahih Muslim, Nr. 2328). Alles Nähere im Brennpunkt 4:34."},
 {vers: "Verse 36–70: Rechte, Gebet, Treuhand und Gehorsam", text: "Vers 36 ist ein Katalog der Pflichten in zehn Schritten: Allah allein dienen, Güte zu Eltern, Verwandten, Waisen, Armen, dem nahen und dem fernen Nachbarn, dem Gefährten an der Seite, dem Reisenden und den Abhängigen – „Allah liebt nicht den Eingebildeten und Prahler“. Vers 43 ist eine Station im schrittweisen Alkoholverbot: „Nähert euch nicht dem Gebet, während ihr betrunken seid“ – nach ʿAlīs Bericht hatte ein Betrunkener beim Vorbeten Sure Al-Kāfirūn falsch gelesen (Sunan at-Tirmidhī, Nr. 3026); im selben Vers kommt die Erlaubnis des Tayammum. Vers 48: Schirk vergibt Allah nicht, alles andere, wem Er will. Vers 58 ist die Verfassung des Gemeinwesens: „Allah befiehlt euch, anvertraute Güter ihren Eigentümern zurückzugeben und, wenn ihr zwischen Menschen richtet, gerecht zu richten.“ Vers 59 ordnet Autorität: Gehorsam gegenüber Allah, dem Gesandten und den Verantwortlichen – und bei Streit: „Bringt es vor Allah und den Gesandten.“ Vers 65 macht klar, dass Glaube die innere Annahme des prophetischen Urteils verlangt, „ohne Bedrängnis im Herzen“."},
 {vers: "Verse 71–104: Kampf, Heuchler und Gebet in Gefahr", text: "Vers 75 nennt den Grund für Verteidigung: die Unterdrückten Mekkas, „Männer, Frauen und Kinder, die rufen: Unser Herr, bring uns heraus aus dieser Stadt der Ungerechten“. Die Verse 88–91 behandeln Heuchler, die zur kriegführenden Seite übergelaufen waren; 4:89 wird oft ohne 4:90 zitiert, der alle Neutralen und Friedensbereiten ausdrücklich schützt (ausführlich im Brennpunkt 4:89). Die Verse 92–93 regeln die Tötung eines Gläubigen: bei Versehen Blutgeld und Sklavenbefreiung, bei Vorsatz die schwerste Drohung des Korans. Vers 94: „Wenn ihr auf dem Weg Allahs auszieht, dann prüft genau nach und sagt nicht zu dem, der euch den Friedensgruß bietet: Du bist kein Gläubiger.“ Vers 97 tadelt die, die in Mekka blieben, obwohl sie hätten auswandern können (Sahih al-Buchari, Nr. 4596). Die Verse 101–103 erlauben das Kürzen des Gebets auf Reisen und regeln das Gebet in Gefahr: Selbst im Gefecht fällt das Gebet nicht aus – „das Gebet ist den Gläubigen zu festgesetzten Zeiten vorgeschrieben“."},
 {vers: "Verse 105–152: Gerechtigkeit, Vergebung und Heuchelei", text: "Die Verse 105–113 stammen nach den Tafsir-Werken aus einem Diebstahlsfall, bei dem ein Muslim sich herauswinden und einen unschuldigen Juden beschuldigen wollte – und der Koran stellt sich auf die Seite des Unschuldigen: „Sei kein Fürsprecher der Verräter.“ Vers 110 öffnet die Tür: „Wer Böses tut oder sich selbst Unrecht zufügt und dann Allah um Vergebung bittet, wird Allah allvergebend und barmherzig finden.“ Vers 128 empfiehlt Ehepartnern, sich zu einigen, statt sich zu trennen: „Einigung ist besser.“ Vers 135 ist einer der stärksten Gerechtigkeitsverse überhaupt: „Seid Wahrer der Gerechtigkeit, Zeugen für Allah, und sei es gegen euch selbst oder die Eltern und nächsten Verwandten.“ Vers 142 beschreibt die Heuchler beim Gebet: träge, um gesehen zu werden, Allahs nur wenig gedenkend (vgl. Lektion 17, Al-Māʿūn)."},
 {vers: "Verse 153–176: Schriftbesitzer, ʿĪsā und das letzte Wort", text: "Die Sure spricht mit den Schriftbesitzern. Über ʿĪsā sagt sie: „Sie haben ihn weder getötet noch gekreuzigt, sondern es erschien ihnen nur so … Allah hat ihn zu Sich emporgehoben“ (4:157–158). Vers 163 stellt den Propheten ﷺ in die Reihe von Nūḥ, Ibrāhīm, Mūsā und ʿĪsā – eine Offenbarung, viele Gesandte. Vers 171 mahnt die Christen: „Übertreibt nicht in eurer Religion … ʿĪsā, der Sohn Maryams, ist nur Allahs Gesandter … Sagt nicht ‚Drei‘.“ Und das letzte Wort ist Erbrecht: die kalāla – ein Mensch ohne Eltern und Kinder. Selbst die schwierigste Erbfrage hat Allah nicht offen gelassen: „Allah macht es euch klar, damit ihr nicht irregeht.“"}
],
ahadith: [
 {text: "Ibn Masʿūd las dem Propheten ﷺ aus An-Nisāʾ vor; bei Vers 41 sagte dieser: „Genug jetzt“ – und seine Augen flossen über.", quelle: "Sahih al-Buchari, Nr. 5050; Sahih Muslim, Nr. 800"},
 {text: "„Meidet die sieben verderblichen Dinge“: Schirk, Zauberei, ungerechtes Töten, Zinsnehmen, Verschlingen von Waisenvermögen, Flucht aus der Schlacht, Verleumdung keuscher gläubiger Frauen – vgl. 4:10 und 4:31.", quelle: "Sahih al-Buchari, Nr. 2766; Sahih Muslim, Nr. 89"},
 {text: "„Die Besten von euch sind die Besten zu ihren Frauen.“ – die Sunna zu 4:19.", quelle: "Sunan at-Tirmidhī, Nr. 3895; sahih"},
 {text: "„Gebt die festgesetzten Anteile denen, denen sie zustehen; was übrig bleibt, gehört dem nächsten männlichen Verwandten.“ – die Grundregel des Erbrechts.", quelle: "Sahih al-Buchari, Nr. 6732; Sahih Muslim, Nr. 1615"}
],
hanafi: "An-Nisāʾ ist eine Fundgrube hanafitischen Fiqhs – hier die wichtigsten Punkte: (1) Erbrecht: Neben den Quotenerben (aṣḥāb al-furūḍ) und den Resterben (ʿaṣaba) erben nach der hanafitischen Schule auch die entfernteren Verwandten über die weibliche Linie (dhawū l-arḥām), wenn keine der ersten beiden Gruppen vorhanden ist – die Schule lässt das Vermögen lieber in der Familie, als es an die Staatskasse fallen zu lassen. (2) Brautgabe (4:4, 4:24): Mindestbrautgabe sind nach der Schule zehn Dirham; wurde keine festgelegt, steht der Frau die übliche Brautgabe (mahr al-mithl) zu. (3) Ehe: Eine volljährige, geistig gesunde Frau kann ihre Ehe nach Abū Ḥanīfa selbst gültig schließen; der Vormund kann aber bei fehlender Ebenbürtigkeit (kafāʾa) Einspruch erheben – empfohlen bleibt, den Vater bzw. Vormund einzubeziehen. (4) Tayammum (4:43): zwei Schläge auf reinen Boden – einer für das Gesicht, einer für beide Arme bis einschließlich der Ellbogen; erlaubt mit allem, was zur Erdart gehört (Erde, Sand, Stein). (5) Reisegebet (4:101): Für Hanafiten ist das Kürzen der Vier-Rakʿa-Gebete auf Reisen (ab ca. 77–88 km nach verbreiteter Umrechnung) nicht nur erlaubt, sondern wādschib – wer vier betet, hat die Sunna verletzt.",
umsetzung: [
 "Lerne 4:36 als Pflichtenliste deines Alltags: Eltern, Verwandte, Waisen, Arme, Nachbarn, Gefährten, Reisende – prüfe diese Woche, zu welcher Gruppe dein Verhältnis am schwächsten ist, und tue dort eine konkrete Sache.",
 "Lies 4:135 und frag dich ehrlich: Würde ich auch gegen mich selbst oder meine Familie die Wahrheit bezeugen? Gerechtigkeit beginnt dort, wo sie etwas kostet.",
 "Wenn du heiratest oder verheiratet bist: Nimm 4:19 als Ehe-Grundsatz – im Guten zusammenleben, und bei Abneigung daran denken, dass Allah in das Ungeliebte Gutes legen kann. Bei Streit 4:35 vor jeder Trennung: Schlichter aus beiden Familien.",
 "Kümmere dich um ein Waisenkind – durch Patenschaft, Spende oder persönliche Begleitung. Die Sure beginnt mit den Waisen, weil sie keine Lobby haben.",
 "Lerne die Grundzüge des Erbrechts (oder lass dich beraten) und schreibe ein Testament nach islamischen Regeln – damit dein Nachlass später nicht zum Streit wird."
]
},

// ───────────────────────── Lektion 93: Az-Zalzala ─────────────────────────
{
sure: 99, offb: 93, name: "Az-Zalzala", arab: "سُورَةُ الزَّلْزَلَةِ", de: "Das Beben", verse: 8, ort: "Medina",
zeit: "Die Kairoer Ausgabe zählt sie als medinensisch; viele Gelehrte (u. a. nach Ibn Masʿūd und Dschābir) halten sie für mekkanisch – ihr Stil spricht für die frühe Zeit",
kurz: "Acht Verse, die die Erde selbst zum Zeugen machen. Am Jüngsten Tag bebt sie ihr letztes Beben, wirft ihre Lasten heraus – die Toten, die verborgenen Schätze –, und der Mensch fragt fassungslos: „Was ist mit ihr?“ Dann „erzählt sie ihre Nachrichten“: was auf ihr getan wurde, an welchem Ort, zu welcher Zeit. Die Menschen kommen in Gruppen hervor, um ihre Taten zu sehen. Und dann folgen die zwei Verse, die der Prophet ﷺ „den einzigartigen, umfassenden Vers“ nannte: Wer auch nur das Gewicht eines Stäubchens Gutes tut, wird es sehen – und wer auch nur das Gewicht eines Stäubchens Böses tut, wird es sehen. Nichts geht verloren, nichts ist zu klein.",
schluessel: {arab: "فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ ۝ وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ", ueb: "Wer nun das Gewicht eines Stäubchens an Gutem tut, wird es sehen. Und wer das Gewicht eines Stäubchens an Bösem tut, wird es sehen.", ref: "99:7–8"},
kontext: ["Zur Einordnung ehrlich: Die Kairoer Standardausgabe, der diese App folgt, führt Az-Zalzala als medinensisch. Viele Gelehrte sehen sie dagegen als mekkanisch, und ihr Inhalt – Jüngster Tag, kurze, wuchtige Verse – passt zu den frühen Suren, die du in den Lektionen 7, 14 und 30 kennengelernt hast. Beides wird vertreten; für das Verständnis ändert es wenig.",
"Die Erde ist in dieser Sure keine Kulisse, sondern Zeugin. Die Araber kannten Beben, aber nicht so: Diesmal bebt die Erde nicht zufällig, sondern auf Befehl, „weil dein Herr es ihr eingegeben hat“ (99:5). Sie spuckt aus, was sie verborgen hielt – auch das, was Menschen in ihr vergraben haben, um es zu verstecken.",
"Die Schlussverse 7–8 wurden zum Prinzip. Als der Prophet ﷺ nach den Esel-Besitzern gefragt wurde (welchen Lohn sie haben), sagte er: „Darüber ist mir nichts herabgesandt worden außer diesem einzigartigen, umfassenden Vers: Wer das Gewicht eines Stäubchens Gutes tut, wird es sehen …“ (Sahih al-Buchari, Nr. 2371; Sahih Muslim, Nr. 987). Für jede Frage nach dem Wert einer kleinen Tat gibt es also eine Antwort: Sie zählt."],
asbab: ["Kein gesicherter Einzelanlass überliefert."],
begriffe: [
 {arab: "زِلْزَال", tr: "zilzāl", wurzel: "z-l-z-l", erkl: "Das Beben – die Verdopplung der Laute (zal-zal) ahmt das Hin-und-her-Schütteln nach. „Ihr Beben“ (zilzālahā): das letzte, das ihr eigentümliche Beben, nach dem nichts mehr ist wie vorher."},
 {arab: "أَثْقَالَهَا", tr: "athqālahā", wurzel: "th-q-l", erkl: "„Ihre Lasten“ (99:2) – die Toten und alles Verborgene in ihr. Die Erde hat getragen, was man ihr anvertraut hat; jetzt gibt sie es zurück."},
 {arab: "تُحَدِّثُ أَخْبَارَهَا", tr: "tuḥaddithu achbārahā", wurzel: "ḥ-d-th / ch-b-r", erkl: "„Sie erzählt ihre Nachrichten“ (99:4) – die Erde als Zeugin: Sie bezeugt, was jeder Mensch und jede Gemeinschaft auf ihr getan hat. Jeder Gebetsplatz und jeder Tatort wird sprechen."},
 {arab: "أَشْتَاتًا", tr: "aschtātan", wurzel: "sch-t-t", erkl: "„In getrennten Gruppen“ (99:6) – jeder nach seiner Art, seinen Taten, seinem Weg. Die Gemeinschaften der Welt lösen sich auf und sortieren sich neu."},
 {arab: "مِثْقَال ذَرَّة", tr: "mithqāl dharra", wurzel: "th-q-l / dh-r-r", erkl: "„Das Gewicht eines Stäubchens“ – dharra: die kleinste den Arabern vorstellbare Einheit (das Stäubchen im Sonnenstrahl, die winzige Ameise). Die Waage Allahs hat keine Mindestmenge."}
],
tafsir: [
 {vers: "Verse 1–5: Die Erde spricht", text: "„Wenn die Erde mit ihrem Beben erschüttert wird, und die Erde ihre Lasten herausgibt, und der Mensch sagt: Was ist mit ihr? – an jenem Tag wird sie ihre Nachrichten erzählen, weil dein Herr es ihr eingegeben hat.“ – Ibn Kathīr: Der Mensch, der sein Leben lang die Erde als stumm und verlässlich behandelte, steht plötzlich vor einer Zeugin. As-Saʿdī: Die Erde bezeugt Gutes wie Böses – deshalb empfehlen Gelehrte, an verschiedenen Orten zu beten und Gutes zu tun, damit viele Orte für dich sprechen."},
 {vers: "Verse 6–8: Das Stäubchen", text: "„An jenem Tag kommen die Menschen in getrennten Gruppen hervor, damit ihnen ihre Taten gezeigt werden. Wer das Gewicht eines Stäubchens an Gutem tut, wird es sehen; und wer das Gewicht eines Stäubchens an Bösem tut, wird es sehen.“ – Al-Qurṭubī: Diese beiden Verse sind eine ganze Moral in einem Satz: Unterschätze keine kleine gute Tat, denn sie wird sichtbar; und unterschätze keine kleine Sünde, denn auch sie wird sichtbar. Der Prophet ﷺ sagte: „Unterschätze nichts vom Guten, und sei es, deinem Bruder mit freundlichem Gesicht zu begegnen“ (Sahih Muslim, Nr. 2626). Beachte auch den Zusammenhang mit Lektion 30 (Al-Qāriʿa): Dort die Waage, hier ihre Feinheit."}
],
ahadith: [
 {text: "Auf die Frage nach dem Lohn für Esel sagte der Prophet ﷺ: „Darüber ist mir nichts herabgesandt worden außer diesem einzigartigen, umfassenden Vers: Wer das Gewicht eines Stäubchens Gutes tut, wird es sehen …“", quelle: "Sahih al-Buchari, Nr. 2371; Sahih Muslim, Nr. 987"},
 {text: "„Unterschätze nichts vom Guten, und sei es, deinem Bruder mit einem freundlichen Gesicht zu begegnen.“", quelle: "Sahih Muslim, Nr. 2626"},
 {text: "„Hütet euch vor den kleingeschätzten Sünden – sie sammeln sich bei einem Menschen, bis sie ihn zugrunde richten.“", quelle: "Musnad Aḥmad, Nr. 3818; von den Gelehrten als sahih eingestuft"},
 {text: "Ehrlichkeitshinweis: Die verbreitete Überlieferung, Az-Zalzala wiege die Hälfte des Korans auf (at-Tirmidhī, Nr. 2894), gilt nach den Hadith-Kritikern als schwach. Der Wert der Sure steht durch ihren Inhalt und den Buchari-Hadith fest.", quelle: "at-Tirmidhī, Nr. 2894 (ḍaʿīf)"}
],
hanafi: null,
umsetzung: [
 "Sammle diese Woche bewusst ‚Stäubchen-Taten‘: ein Lächeln, ein Gruß, ein Stein vom Weg, ein kleines Geschenk – jeden Tag eine, die niemand bemerkt. Allah bemerkt sie.",
 "Prüfe deine ‚kleinen‘ Sünden: Welche Gewohnheit hältst du für zu klein, um zu zählen (ein Blick, ein Wort, eine Ausrede)? Nach 99:8 gibt es keine zu kleine.",
 "Bete an verschiedenen Orten – zuhause, im Park, in verschiedenen Moscheen – damit, wie die Gelehrten sagen, viele Orte am Jüngsten Tag für dich sprechen.",
 "Lerne 99:7–8 auswendig und nutze sie, wenn dich jemand fragt, ob eine kleine gute Tat ‚überhaupt etwas bringt‘."
]
},

// ───────────────────────── Lektion 94: Al-Ḥadīd ─────────────────────────
{
sure: 57, offb: 94, name: "Al-Ḥadīd", arab: "سُورَةُ الْحَدِيدِ", de: "Das Eisen", verse: 29, ort: "Medina",
zeit: "Medina – der Hinweis auf die, die „vor dem Sieg“ spendeten (57:10), legt eine spätere Zeit nahe; ein Bericht von Ibn Masʿūd zu Vers 16 deutet auf eine frühere",
kurz: "Eine Sure, die das Herz weich machen will. Sie beginnt mit Allahs Größe – „Er ist der Erste und der Letzte, der Offenkundige und der Verborgene“ – und wendet sich dann an die Gläubigen mit zwei Aufrufen: Gebt aus von dem, worüber Allah euch zu Nachfolgern gemacht hat, und lasst eure Herzen nicht hart werden. Vers 16 ist einer der berührendsten Weckrufe des Korans: „Ist es für die Gläubigen nicht Zeit, dass ihre Herzen demütig werden beim Gedenken Allahs?“ Dazu Bilder vom Licht, das den Gläubigen am Jüngsten Tag vorauseilt, während die Heuchler bitten: „Wartet auf uns, damit wir etwas von eurem Licht nehmen!“ Und das Eisen, nach dem die Sure benannt ist: Allah sandte es herab, „in dem gewaltige Kraft und Nutzen für die Menschen ist“ – Werkzeug, Waffe und Prüfung zugleich.",
schluessel: {arab: "أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللَّهِ", ueb: "Ist es für die Gläubigen nicht Zeit, dass ihre Herzen demütig werden beim Gedenken Allahs?", ref: "57:16"},
kontext: ["Ibn Masʿūd sagte über Vers 16: „Zwischen unserem Islam und dem Tadel, den Allah uns mit diesem Vers erteilte, lagen nur vier Jahre“ (Sahih Muslim, Nr. 3027). Der Vers richtet sich also nicht an Ungläubige, sondern an Gläubige, deren Eifer mit der Zeit abgekühlt war. Das ist eine der ehrlichsten Stellen des Korans: Auch die besten Gemeinschaften brauchen ab und zu einen Weckruf.",
"Vers 10 unterscheidet zwischen denen, die „vor dem Sieg“ spendeten und kämpften, und denen, die es danach taten: Beide bekommen „das Beste“ versprochen, aber die Ersten stehen höher. Wer gibt, wenn die Sache schwach und unsicher ist, hat mehr Mut bewiesen als der, der gibt, wenn sie schon gewonnen hat.",
"Der Name ‚Das Eisen‘ (57:25) steht in einem Vers, der die ganze Ordnung der Welt in einem Satz zusammenfasst: Allah sandte Gesandte mit klaren Beweisen, mit Buch und Waage (Gerechtigkeit) – „und Wir haben das Eisen herabgesandt, in dem gewaltige Kraft liegt und Nutzen für die Menschen“. Wahrheit, Gerechtigkeit und die Macht, sie zu schützen: Alle drei gehören zusammen."],
asbab: [
 {text: "57:16: Ibn Masʿūd: Zwischen dem Islam der ersten Gläubigen und diesem tadelnden Vers lagen nur vier Jahre.", quelle: "Sahih Muslim, Nr. 3027"}
],
begriffe: [
 {arab: "الْأَوَّلُ وَالْآخِرُ", tr: "al-awwal wa-l-āchir", wurzel: "ʾ-w-l / ʾ-ch-r", erkl: "„Der Erste und der Letzte“ (57:3) – vor Ihm war nichts, nach Ihm ist nichts. Mit „der Offenkundige und der Verborgene“ (aẓ-ẓāhir wa-l-bāṭin) vier Namen in einem Vers, die der Prophet ﷺ im Gebet vor dem Schlafen erklärte (Sahih Muslim, Nr. 2713)."},
 {arab: "مُسْتَخْلَفِين", tr: "mustachlafīn", wurzel: "ch-l-f", erkl: "„Zu Nachfolgern/Verwaltern eingesetzt“ (57:7): „Gebt aus von dem, worüber Er euch als Verwalter eingesetzt hat.“ Dein Besitz ist nicht deiner – du verwaltest ihn für eine Zeit. Das macht das Geben leicht."},
 {arab: "قَرْضًا حَسَنًا", tr: "qarḍan ḥasanan", wurzel: "q-r-ḍ", erkl: "„Ein schönes Darlehen“ (57:11, 57:18) – Spenden für Allah als Darlehen, das Er vervielfacht zurückzahlt. Der Reichste leiht vom Bedürftigen, damit dieser gewinnt."},
 {arab: "نُور", tr: "nūr", wurzel: "n-w-r", erkl: "Licht – am Jüngsten Tag eilt den Gläubigen ihr Licht „vor ihnen und zu ihrer Rechten“ voraus (57:12). Das Licht entsteht aus dem, was du im Diesseits getan hast; leihen kann man es nicht (57:13)."},
 {arab: "تَخْشَعَ", tr: "tachschaʿa", wurzel: "ch-sch-ʿ", erkl: "„Demütig werden“ – chuschūʿ: die innere Stille und Ehrfurcht, die sich in Haltung und Gebet zeigt. Das Gegenteil: „Ihre Herzen wurden hart (qasat)“ (57:16) – wie bei denen vor ihnen, denen die Zeit zu lang wurde."},
 {arab: "رَهْبَانِيَّة", tr: "rahbāniyya", wurzel: "r-h-b", erkl: "Mönchtum (57:27) – die Christen „erfanden es; Wir haben es ihnen nicht vorgeschrieben“, und viele hielten es nicht ein. Der Islam ehrt die Hingabe, lehnt aber die Weltflucht als Pflicht ab: Gott dienen mitten im Leben."},
 {arab: "الْحَدِيد", tr: "al-ḥadīd", wurzel: "ḥ-d-d", erkl: "Das Eisen (57:25) – „herabgesandt“, mit „gewaltiger Kraft und Nutzen für die Menschen“. Werkzeug für Ackerbau und Bau, Mittel zur Verteidigung der Gerechtigkeit. Kraft ist im Islam weder gut noch böse – entscheidend ist, wem sie dient."}
],
tafsir: [
 {vers: "Verse 1–6: Allahs Größe", text: "„Allah preist, was in den Himmeln und auf der Erde ist.“ Dann der Vers der vier Namen (57:3) und die Nähe Allahs: „Er ist mit euch, wo immer ihr seid“ (57:4) – mit Wissen und Fürsorge, wie die Gelehrten erklären (vgl. Lektion 34, Qāf: näher als die Halsschlagader). Ibn Kathīr: Die Sure baut zuerst die Ehrfurcht auf, bevor sie zum Geben auffordert – wer Allahs Größe erkannt hat, für den wird Besitz klein."},
 {vers: "Verse 7–11: Glauben und Geben", text: "„Glaubt an Allah und Seinen Gesandten und gebt aus von dem, worüber Er euch zu Verwaltern gemacht hat.“ Vers 10 stellt die Frage: „Was ist mit euch, dass ihr nicht auf Allahs Weg ausgebt, wo doch das Erbe der Himmel und der Erde Allah gehört?“ – Alles, was du festhältst, gibst du am Ende sowieso ab; nur was du jetzt gibst, bleibt dir. Dann die Rangordnung der Spender und das Versprechen des schönen Darlehens."},
 {vers: "Verse 12–19: Licht und harte Herzen", text: "Die Szene des Jüngsten Tages: Das Licht der Gläubigen eilt ihnen voraus. Die Heuchler rufen: „Wartet auf uns, damit wir etwas von eurem Licht nehmen!“ – „Kehrt zurück und sucht Licht!“ Eine Mauer mit einem Tor wird zwischen ihnen errichtet, innen Barmherzigkeit, außen Strafe. Die Heuchler: „Waren wir nicht mit euch?“ – „Doch, aber ihr habt euch selbst der Versuchung ausgesetzt, gezögert, gezweifelt, und Wunschdenken hat euch getäuscht.“ Dann der Weckruf 57:16 an die Gläubigen, und Vers 17 als Trost: „Wisst, dass Allah die Erde nach ihrem Tod belebt“ – so wie Er tote Erde belebt, belebt Er auch harte Herzen. As-Saʿdī: Kein Herz ist zu hart, um durch Gedenken, Koran und Reue wieder weich zu werden."},
 {vers: "Verse 20–29: Das Diesseits, die Vorherbestimmung und das Eisen", text: "Vers 20 beschreibt das diesseitige Leben in fünf Stufen: Spiel, Zerstreuung, Schmuck, gegenseitiges Prahlen, Wettstreit um mehr Besitz und Kinder – wie Regen, der Pflanzen wachsen lässt, die dann gelb werden und zerfallen (vgl. Lektion 16, At-Takāthur). Vers 21: „Wetteifert nach Vergebung … und einem Paradies, so breit wie Himmel und Erde.“ Die Verse 22–23 schenken innere Ruhe: Kein Unglück trifft, das nicht vorher aufgezeichnet war – „damit ihr nicht betrübt seid über das, was euch entgangen ist, und nicht übermütig über das, was Er euch gegeben hat“. Dann Vers 25 mit dem Eisen und der Waage, die Prophetenkette von Nūḥ und Ibrāhīm bis ʿĪsā, und das Mönchtum (57:27). Schluss: Den Gläubigen der Schriftbesitzer, die auch an den Propheten ﷺ glauben, verspricht Vers 28 doppelten Lohn."}
],
ahadith: [
 {text: "Ibn Masʿūd: „Zwischen unserem Islam und dem Tadel durch diesen Vers (57:16) lagen nur vier Jahre.“", quelle: "Sahih Muslim, Nr. 3027"},
 {text: "Das Gebet vor dem Schlafen: „O Allah, Du bist der Erste, vor Dir ist nichts; Du bist der Letzte, nach Dir ist nichts; Du bist der Offenkundige, über Dir ist nichts; Du bist der Verborgene, unter Dir ist nichts …“", quelle: "Sahih Muslim, Nr. 2713"},
 {text: "„Sieben wird Allah in Seinem Schatten Schatten spenden …“ – darunter „ein Mann, der so heimlich spendet, dass seine Linke nicht weiß, was seine Rechte gibt“, und „ein Mann, der Allahs allein gedenkt, und seine Augen fließen über“.", quelle: "Sahih al-Buchari, Nr. 660; Sahih Muslim, Nr. 1031"},
 {text: "„Wisse, dass das, was dich getroffen hat, dich nicht verfehlen konnte, und was dich verfehlt hat, dich nicht treffen konnte.“ – zu 57:22–23.", quelle: "Sunan at-Tirmidhī, Nr. 2516; sahih"}
],
hanafi: null,
umsetzung: [
 "Stell dir 57:16 als persönliche Frage: Ist es für mich nicht Zeit? Wähle EINEN Bereich, in dem dein Herz hart geworden ist (Gebet ohne Gefühl, Koran ohne Nachdenken), und gib ihm diese Woche bewusst Zeit.",
 "Lerne das Gebet mit den vier Namen (Muslim 2713) für vor dem Schlafen – es verbindet die Sure mit deinem täglichen Ritual.",
 "Behandle dein Geld als Verwaltung (57:7): Lege einen festen Anteil deines Einkommens für Spenden fest, bevor du den Rest ausgibst – so wird Geben zur Gewohnheit, nicht zur Ausnahme.",
 "Nutze 57:22–23 bei Verlust und Erfolg: Bei Verlust nicht verzweifeln, bei Erfolg nicht übermütig werden – beides war aufgeschrieben, beides ist Prüfung."
]
},

// ───────────────────────── Lektion 95: Muḥammad ─────────────────────────
{
sure: 47, offb: 95, name: "Muḥammad", arab: "سُورَةُ مُحَمَّدٍ", de: "Muḥammad", verse: 38, ort: "Medina",
zeit: "Frühmedinensisch, nach der Hidschra und rund um die Schlacht von Badr (1–2 n. H.) – in der Zeit, als der Krieg mit den Quraisch begann",
kurz: "Die einzige Sure, die nach dem Propheten ﷺ benannt ist – und sie spricht in eine Kriegszeit hinein. Die Quraisch hatten die Muslime aus Mekka vertrieben und rüsteten zum Angriff auf Medina. Die Sure stellt zwei Lager gegenüber: die, die ungläubig sind und andere vom Weg Allahs abhalten, und die, die glauben und an das glauben, was auf Muḥammad ﷺ herabgesandt wurde. Sie regelt den Kampf und den Umgang mit Gefangenen (47:4 – ausführlich im Brennpunkt-Modul), beschreibt die vier Flüsse des Paradieses, entlarvt die Heuchler, die beim Kampfaufruf „wie im Todeskampf“ blicken, und stellt die Frage, die durch die Jahrhunderte hallt: „Denken sie denn nicht über den Koran nach – oder liegen auf ihren Herzen Schlösser?“",
schluessel: {arab: "أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَا", ueb: "Denken sie denn nicht über den Koran nach? Oder sind auf (ihren) Herzen deren Schlösser?", ref: "47:24"},
kontext: ["Die Muslime hatten Mekka verlassen müssen; ihr Besitz war beschlagnahmt, ihre Schwachen wurden weiter verfolgt. In Medina entstand ein kleines Gemeinwesen, das die Quraisch auslöschen wollten. In diese Lage spricht die Sure: Sie gibt der jungen Gemeinde die Erlaubnis und die Regeln zur Verteidigung – und sie verlangt Standhaftigkeit: „Wenn ihr Allah helft, hilft Er euch und festigt eure Füße“ (47:7).",
"Vers 13 erinnert an die Vertreibung: „Wie manche Stadt, die stärker war als deine Stadt, die dich vertrieben hat …“ Die Tafsir-Werke berichten, dass der Prophet ﷺ beim Verlassen Mekkas zurückschaute und sprach: Du bist das liebste Land Allahs und mir das liebste – hätte man mich nicht vertrieben, wäre ich nicht gegangen (vgl. at-Tirmidhī, Nr. 3925, aus Lektion 29). Dass diese Worte den Anlass des Verses bilden, ist ein Tafsir-Bericht, nicht sahih gesichert.",
"Zum Kampfvers 47:4: Er spricht von der Begegnung auf dem Schlachtfeld (liqāʾ) und regelt sofort das Ende des Tötens: Sobald der Gegner kampfunfähig ist, gibt es Gefangenschaft – und dann Freilassung aus Gnade oder Lösegeld, „bis der Krieg seine Lasten ablegt“. Der Vers beschreibt Krieg als zeitlich begrenzten Zustand, nicht als Dauerzustand. Mehr dazu, mit Hukm und Gesprächsanleitung, im Brennpunkt-Modul."],
asbab: ["Für die Sure insgesamt ist kein Einzelanlass sahih überliefert; sie spricht in die Lage der ersten Kriegsjahre. Zu 47:13 berichten Tafsir-Werke den Abschied des Propheten ﷺ von Mekka als Anlass – diese Verbindung ist nicht sahih gesichert."],
begriffe: [
 {arab: "أَضَلَّ أَعْمَالَهُمْ", tr: "aḍalla aʿmālahum", wurzel: "ḍ-l-l", erkl: "„Er lässt ihre Werke fehlgehen“ (47:1) – Taten ohne Glauben verlieren sich wie Wasser im Sand. Gegenstück für die Gläubigen: „Er tilgt ihre bösen Taten und bessert ihren Zustand (bāl)“ (47:2)."},
 {arab: "فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً", tr: "fa-immā mannan baʿdu wa-immā fidāʾan", wurzel: "m-n-n / f-d-y", erkl: "„Danach entweder Begnadigung oder Lösegeld“ (47:4) – die zwei im Vers genannten Wege mit Gefangenen. Siehe Brennpunkt 47:4."},
 {arab: "إِن تَنصُرُوا اللَّهَ", tr: "in tanṣurū llāh", wurzel: "n-ṣ-r", erkl: "„Wenn ihr Allah helft“ (47:7) – Allah braucht keine Hilfe; gemeint ist: Seinem Dīn, Seinen Geboten, Seiner Sache. Dann „festigt Er eure Füße“ – Standhaftigkeit ist Lohn, nicht Eigenleistung."},
 {arab: "أَنْهَار", tr: "anhār", wurzel: "n-h-r", erkl: "Flüsse – 47:15 nennt vier Flüsse des Paradieses: Wasser, das nie schal wird, Milch, deren Geschmack sich nie ändert, Wein, köstlich für die Trinkenden (ohne Rausch und Kopfschmerz, 37:47), und geläuterter Honig."},
 {arab: "يَتَدَبَّرُون", tr: "yatadabbarūn", wurzel: "d-b-r", erkl: "„Sie denken nach“ – tadabbur: wörtlich auf das Ende (dubur) einer Sache schauen, sie bis zu ihren Folgen durchdenken. Genau das will diese App: den Koran nicht nur lesen, sondern durchdenken."},
 {arab: "أَقْفَال", tr: "aqfāl", wurzel: "q-f-l", erkl: "Schlösser (47:24) – das Bild des verschlossenen Herzens. Die Schlösser hat der Mensch selbst angebracht: durch Sünde, Hochmut und Gleichgültigkeit. Der Schlüssel heißt tadabbur."},
 {arab: "يَسْتَبْدِلْ", tr: "yastabdil", wurzel: "b-d-l", erkl: "„Er wird (euch) austauschen“ (47:38): „Wenn ihr euch abwendet, wird Er an eure Stelle ein anderes Volk setzen, die dann nicht so sind wie ihr.“ Allah braucht niemanden – wir brauchen Ihn."}
],
tafsir: [
 {vers: "Verse 1–15: Zwei Lager und die Regeln des Kampfes", text: "Die Sure beginnt mit dem Gegensatz: Werke der Abhaltenden verlieren sich, Werke der Gläubigen werden angenommen. Vers 3 nennt den Grund: Die einen folgen dem Falschen, die anderen der Wahrheit von ihrem Herrn. Vers 4 regelt die Feldschlacht – und begrenzt sie sofort: Gefangenschaft statt Töten, danach Freilassung oder Lösegeld (siehe Brennpunkt 47:4). Vers 7: „Wenn ihr Allah helft, hilft Er euch.“ Vers 12 vergleicht die Leugner mit Vieh, das nur frisst. Vers 15 malt das Paradies mit vier Flüssen und stellt die Frage: Sind diese gleich denen, die ewig im Feuer bleiben und siedendes Wasser trinken müssen?"},
 {vers: "Verse 16–30: Die Heuchler", text: "Heuchler sitzen beim Propheten ﷺ, hören zu und fragen danach spöttisch: „Was hat er eben gesagt?“ (47:16) – Allah hat ihre Herzen versiegelt, weil sie ihren Neigungen folgen. Wenn eine Sure mit Kampfbefehl herabkommt, blicken sie „mit dem Blick dessen, der vor dem Tod in Ohnmacht fällt“ (47:20). Vers 22 warnt: „Würdet ihr, wenn ihr euch abwendet, nicht Unheil im Land stiften und eure Verwandtschaftsbande zerreißen?“ – Abū Huraira las diesen Vers zum Hadith über die Verwandtschaft vor (Sahih al-Buchari, Nr. 4830; Sahih Muslim, Nr. 2554). Dann die Kernfrage 47:24 über die verschlossenen Herzen. Vers 30: Allah kennt die Heuchler – „du würdest sie an der Art ihres Redens erkennen“. Ibn Kathīr: Die Sprache verrät das Herz."},
 {vers: "Verse 31–38: Prüfung, Geben und das Austauschen", text: "„Wir werden euch gewiss prüfen, bis Wir die unter euch kennen, die sich abmühen und standhaft sind“ (47:31). Vers 33: „Gehorcht Allah und dem Gesandten, und macht eure Werke nicht zunichte.“ Vers 35 verbietet, aus Schwäche um Frieden zu betteln, wenn man die Oberhand hat – im Zusammenhang der Kriegslage, nicht als Verbot von Friedensverträgen (die der Prophet ﷺ selbst schloss, z. B. Ḥudaibiya, und 8:61 ausdrücklich empfiehlt). Vers 36: „Das diesseitige Leben ist nur Spiel und Zerstreuung.“ Und Vers 38: Wer geizt, „geizt nur gegen sich selbst. Allah ist der Unbedürftige, und ihr seid die Bedürftigen.“ Wer sich abwendet, wird ersetzt – die Gefährten fragten, wer dieses andere Volk sei; der Hadith über die Perser, die den Glauben selbst vom Siebengestirn holen würden, wird von den Tafsir-Werken hier angeführt (vgl. Sahih Muslim, Nr. 2546)."}
],
ahadith: [
 {text: "„Als Allah die Schöpfung erschaffen hatte, erhob sich die Verwandtschaft (raḥim) … Allah sagte: Bist du nicht zufrieden, dass Ich verbinde, wer dich verbindet, und abschneide, wer dich abschneidet?“ Abū Huraira sagte: Lest, wenn ihr wollt: „Würdet ihr … eure Verwandtschaftsbande zerreißen?“ (47:22).", quelle: "Sahih al-Buchari, Nr. 4830; Sahih Muslim, Nr. 2554"},
 {text: "„Der starke Gläubige ist besser und Allah lieber als der schwache Gläubige – und in beiden ist Gutes.“ – zum Geist von 47:7 und 47:35.", quelle: "Sahih Muslim, Nr. 2664"},
 {text: "„Wäre der Glaube beim Siebengestirn, würden Männer von diesen (den Persern) ihn erreichen.“ – von den Tafsir-Werken zu 47:38 angeführt.", quelle: "Sahih Muslim, Nr. 2546 (vgl. Sahih al-Buchari, Nr. 4897)"}
],
hanafi: "Zu 47:33 („Macht eure Werke nicht zunichte“): Aus diesem Vers leitet die hanafitische Schule eine ihrer bekannten Besonderheiten ab: Wer ein freiwilliges Gebet oder ein freiwilliges Fasten begonnen hat, für den wird es verbindlich, es zu Ende zu führen; bricht er es ohne Grund ab, muss er es nachholen (qaḍāʾ). Andere Schulen sehen das freiwillige Werk als jederzeit abbrechbar. Praktisch: Fang ein Nafl-Fasten nur an, wenn du es auch durchziehen willst. Zu 47:4 (Gefangene) haben die frühen Hanafiten das Kriegsrecht in eigener Systematik behandelt (al-Dschaṣṣāṣ diskutiert es ausführlich); das ist Staatsrecht für Kriegszeiten und keine Frage, die ein Einzelner heute entscheidet – siehe die Grundsätze im Brennpunkt-Modul.",
umsetzung: [
 "Nimm 47:24 als Lernmotto für diese ganze App: Lies jede Lektion nicht als Information, sondern mit tadabbur – frag bei jedem Vers: Was folgt daraus für mich?",
 "Pflege die Verwandtschaft (47:22 + Hadith): Ruf diese Woche einen Verwandten an, zu dem der Kontakt abgerissen ist.",
 "Wenn du ein freiwilliges Fasten oder Gebet beginnst, führe es zu Ende (hanafitisch verbindlich nach 47:33).",
 "Erinnere dich an 47:38, wenn Geben schwerfällt: Wer geizt, geizt gegen sich selbst. Allah ist reich – du bist der Bedürftige."
]
},

// ───────────────────────── Lektion 96: Ar-Raʿd ─────────────────────────
{
sure: 13, offb: 96, name: "Ar-Raʿd", arab: "سُورَةُ الرَّعْدِ", de: "Der Donner", verse: 43, ort: "Medina",
zeit: "Die Kairoer Ausgabe zählt sie als medinensisch; viele Gelehrte sehen sie wegen ihres Inhalts (Tauhīd, Zeichen, Auferstehung) als mekkanisch – beides wird vertreten",
kurz: "Eine Sure der Zeichen und der Herzensruhe. Sie zeigt Allahs Macht in der Natur – Himmel ohne sichtbare Stützen, Berge und Flüsse, Gärten mit verschiedenen Früchten, die doch vom selben Wasser getränkt werden – und sie lässt sogar den Donner sprechen: „Der Donner preist Ihn mit Seinem Lob, und (ebenso) die Engel aus Furcht vor Ihm“ (13:13). Zwei Verse aus ihr kennt fast jeder Muslim: „Allah ändert nicht den Zustand eines Volkes, bis sie das ändern, was in ihnen selbst ist“ (13:11), und: „Wahrlich, im Gedenken Allahs finden die Herzen Ruhe“ (13:28). Dazu das berühmte Gleichnis vom Schaum: Die Wahrheit ist wie Wasser, das bleibt, die Lüge wie Schaum, der vergeht.",
schluessel: {arab: "أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ", ueb: "Wahrlich, im Gedenken Allahs finden die Herzen Ruhe.", ref: "13:28"},
kontext: ["Zur Einordnung ehrlich: Die Kairoer Ausgabe führt Ar-Raʿd als medinensisch, viele Mufassirūn halten sie für mekkanisch oder für gemischt. Ihr Inhalt erinnert stark an die mekkanischen Suren (vgl. Lektion 34, Qāf; Lektion 41, Yā-Sīn): Zeichen in der Schöpfung, Antworten auf den Auferstehungszweifel, Trost für den Gesandten. Für dein Verständnis ist entscheidend, was sie sagt – nicht, auf welchem Kalenderblatt sie steht.",
"Die Sure antwortet auf die Forderung der Gegner nach einem sichtbaren Wunder (13:7, 13:27, 13:31): „Wenn doch ein Zeichen von seinem Herrn auf ihn herabgesandt würde!“ Die Antwort: Allah lässt in die Irre gehen, wen Er will, und leitet zu Sich, wer sich Ihm zuwendet (13:27). Wunder überzeugen nicht ein verschlossenes Herz – aber Gedenken öffnet ein suchendes (13:28).",
"Zum Donner (13:13) berichten Tafsir-Werke von einem Mann, der hochmütig nach dem ‚Material‘ Allahs fragte und von einem Blitz getroffen wurde; die Überlieferungen dazu sind nicht sahih gesichert. Gesichert ist die Praxis der Gefährten: ʿAbdullāh ibn az-Zubair unterbrach bei Donner das Gespräch und sprach: „Gepriesen sei Der, Den der Donner mit Seinem Lob preist und die Engel aus Furcht vor Ihm“ (Muwaṭṭaʾ Mālik, als Wort Ibn az-Zubairs überliefert)."],
asbab: ["Kein Einzelanlass sahih gesichert. Zu 13:13 nennen Tafsir-Werke Berichte über hochmütige Fragesteller (u. a. ʿĀmir ibn aṭ-Ṭufail und Arbad), die nicht sahih gesichert sind."],
begriffe: [
 {arab: "الرَّعْد", tr: "ar-raʿd", wurzel: "r-ʿ-d", erkl: "Der Donner – im Koran ein Lobpreisender (13:13). Die ganze Schöpfung preist Allah auf ihre Weise (17:44); der Donner tut es hörbar. Dieselbe Wurzel: irtiʿād, das Zittern."},
 {arab: "بِغَيْرِ عَمَدٍ تَرَوْنَهَا", tr: "bi-ġairi ʿamadin taraunahā", wurzel: "ʿ-m-d", erkl: "„Ohne Stützen, die ihr seht“ (13:2) – der Himmel trägt sich ohne sichtbare Säulen. Die Gelehrten: Entweder gibt es keine Säulen, oder es gibt sie, aber unsichtbar – in jedem Fall hält Allah ihn."},
 {arab: "يُغَيِّرُوا مَا بِأَنفُسِهِمْ", tr: "yuġayyirū mā bi-anfusihim", wurzel: "ġ-y-r", erkl: "„Ändern, was in ihnen selbst ist“ (13:11) – das Gesetz der inneren Veränderung: Allah ändert den äußeren Zustand eines Volkes erst, wenn es sich innerlich ändert. Das gilt in beide Richtungen – zum Guten und zum Schlechten."},
 {arab: "مُعَقِّبَات", tr: "muʿaqqibāt", wurzel: "ʿ-q-b", erkl: "„(Engel,) die einander ablösen“ (13:11) – sie bewachen den Menschen „vor ihm und hinter ihm, auf Allahs Befehl“. Vgl. Lektion 36 (Aṭ-Ṭāriq: Über jeder Seele ein Hüter)."},
 {arab: "زَبَد", tr: "zabad", wurzel: "z-b-d", erkl: "Schaum (13:17) – auf dem Hochwasser und auf geschmolzenem Metall. Er ist oben, laut und sichtbar – und vergeht. Das Wasser und das Metall bleiben. So ist es mit Wahrheit und Lüge."},
 {arab: "تَطْمَئِنُّ", tr: "taṭmaʾinnu", wurzel: "ṭ-m-ʾ-n", erkl: "„Sie finden Ruhe“ – dieselbe Wurzel wie an-nafs al-muṭmaʾinna (Lektion 10, Al-Fadschr). 13:28 nennt den Weg dorthin: das Gedenken Allahs."},
 {arab: "يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ", tr: "yamḥū llāhu mā yaschāʾu wa-yuthbit", wurzel: "m-ḥ-w / th-b-t", erkl: "„Allah löscht aus, was Er will, und bestätigt“ (13:39) – und bei Ihm ist die Mutter des Buches (umm al-kitāb). Die Gelehrten: In den Büchern der Engel kann sich etwas ändern (z. B. durch Bittgebet und Verwandtschaftspflege), im Urwissen Allahs nicht."}
],
tafsir: [
 {vers: "Verse 1–7: Zeichen in Himmel und Erde", text: "Der Himmel ohne sichtbare Stützen, Sonne und Mond auf festen Bahnen, die ausgebreitete Erde mit Bergen und Flüssen, Früchte in Paaren, Nacht und Tag. Vers 4 enthält ein feines Zeichen: Nebeneinander liegende Gärten werden mit demselben Wasser getränkt, „und doch bevorzugen Wir die einen im Geschmack vor den anderen“. Ibn Kathīr: Gleiche Ursachen, verschiedene Ergebnisse – das zeigt einen wollenden Schöpfer, nicht blinden Zufall. Vers 5 wundert sich über die, die die Auferstehung leugnen: „Sollen wir, wenn wir Erde geworden sind, wirklich neu erschaffen werden?“ (vgl. Lektion 31)."},
 {vers: "Verse 8–18: Allahs Wissen, der Donner und das Gleichnis vom Schaum", text: "Allah weiß, was jede Frau im Leib trägt (13:8). Ob jemand heimlich oder laut spricht, sich in der Nacht verbirgt oder am Tag umhergeht – es ist für Ihn gleich (13:10). Dann der Vers der Engel und der inneren Veränderung (13:11). Blitz, Wolken und Donner (13:12–13) zeigen Seine Macht. Vers 15 ist ein Sadschda-Vers: „Vor Allah wirft sich nieder, was in den Himmeln und auf der Erde ist, freiwillig oder widerwillig – und ihre Schatten am Morgen und am Abend.“ Vers 16 fragt: „Sind der Blinde und der Sehende gleich, oder die Finsternisse und das Licht?“ Vers 17 bringt das Gleichnis: Regen füllt die Täler, die Flut trägt Schaum; auch geschmolzenes Metall bildet Schaum. „Der Schaum vergeht als nichtiger Abfall, was aber den Menschen nützt, bleibt auf der Erde.“ As-Saʿdī: Lass dich nicht vom Lärm der Lüge beeindrucken – er ist Schaum."},
 {vers: "Verse 19–29: Die Leute des Verstandes und die Ruhe der Herzen", text: "„Ist denn der, der weiß, dass das, was dir herabgesandt wurde, die Wahrheit ist, wie der, der blind ist? Nur die Leute des Verstandes (ūlū l-albāb) bedenken.“ Dann ein ganzes Charakterbild (13:20–24): Sie halten Allahs Bund, verbinden, was Allah zu verbinden befahl (Verwandtschaft), fürchten den Herrn, sind standhaft, beten, spenden heimlich und offen – und „wehren das Böse mit dem Guten ab“. Ihr Lohn: Die Engel treten zu ihnen ein und grüßen: „Friede sei mit euch für das, was ihr standhaft ertragen habt.“ Vers 28 nennt das Geheimnis: „Diejenigen, die glauben und deren Herzen im Gedenken Allahs Ruhe finden – wahrlich, im Gedenken Allahs finden die Herzen Ruhe.“ Al-Qurṭubī: Das Gedenken ist hier auch der Koran selbst."},
 {vers: "Verse 30–43: Trost für den Gesandten", text: "Vers 31: Selbst wenn ein Koran Berge versetzte oder Tote sprechen ließe – die Verstockten würden nicht glauben. Vers 38: Auch die früheren Gesandten hatten Frauen und Kinder; kein Gesandter bringt ein Zeichen außer mit Allahs Erlaubnis. Vers 39: Allah löscht aus und bestätigt, bei Ihm ist die Mutter des Buches. Vers 40 beruhigt den Propheten ﷺ: „Dir obliegt nur die Übermittlung, und Uns obliegt die Abrechnung.“ Der Schlussvers: „Allah genügt als Zeuge zwischen mir und euch.“"}
],
ahadith: [
 {text: "„Wem es gefällt, dass ihm seine Versorgung ausgeweitet und sein Leben verlängert wird, der soll seine Verwandtschaftsbande pflegen.“ – von den Gelehrten zu 13:21 und 13:39 angeführt.", quelle: "Sahih al-Buchari, Nr. 2067; Sahih Muslim, Nr. 2557"},
 {text: "„Nichts wendet die Bestimmung ab außer das Bittgebet, und nichts verlängert das Leben außer die Güte.“", quelle: "Sunan at-Tirmidhī, Nr. 2139; hasan"},
 {text: "„Das Gleichnis dessen, der seines Herrn gedenkt, und dessen, der nicht gedenkt, ist das Gleichnis des Lebenden und des Toten.“ – zu 13:28.", quelle: "Sahih al-Buchari, Nr. 6407"},
 {text: "Bei Donner sprach ʿAbdullāh ibn az-Zubair: „Gepriesen sei Der, Den der Donner mit Seinem Lob preist und die Engel aus Furcht vor Ihm.“", quelle: "Muwaṭṭaʾ Mālik (Wort eines Gefährten, mauqūf)"}
],
hanafi: "Vers 13:15 ist ein Sadschda-Vers: Nach hanafitischer Schule ist die Rezitations-Niederwerfung (sadschdat at-tilāwa) hier wādschib – für den, der rezitiert, und für den, der bewusst zuhört. Mit Takbīr hinab, einmal subḥāna rabbiya l-aʿlā, mit Takbīr hinauf, ohne Taschahhud und Taslīm. Rezitierst du den Vers im Gebet, kannst du die Sadschda sofort im Gebet machen (oder die Rukūʿ bzw. Sadschda des Gebets erfüllt sie, wenn sie unmittelbar folgt). Damit kennst du fünf der vierzehn Sadschda-Verse: 7:206, 13:15, 38:24, 53:62, 96:19.",
umsetzung: [
 "Lebe 13:28 konkret: Wenn Unruhe, Angst oder Grübeln kommen, greif zuerst zum Dhikr (z. B. 100× subḥānallāh oder eine Seite Koran) – bevor du zum Handy greifst.",
 "Arbeite mit 13:11 an dir selbst: Wähle eine Sache, die du in deinem Leben verändert sehen willst, und frag ehrlich: Was muss ich IN mir zuerst ändern?",
 "Sprich bei Donner das Wort Ibn az-Zubairs – so wird ein Naturereignis zum Gedenken.",
 "Übe 13:22: „das Böse mit dem Guten abwehren“ – reagiere diese Woche auf eine unfreundliche Behandlung bewusst mit einer freundlichen Tat."
]
},

// ───────────────────────── Lektion 97: Ar-Raḥmān ─────────────────────────
{
sure: 55, offb: 97, name: "Ar-Raḥmān", arab: "سُورَةُ الرَّحْمَٰنِ", de: "Der Allerbarmer", verse: 78, ort: "Medina",
zeit: "Die Kairoer Ausgabe zählt sie als medinensisch; viele Gelehrte halten sie für mekkanisch – nach der Sīra soll Ibn Masʿūd sie als Erster öffentlich an der Kaaba rezitiert haben",
kurz: "Eine der schönsten Suren des Korans, oft ‚die Braut des Korans‘ genannt. Sie beginnt nicht mit einem Schwur, sondern mit einem Namen: „Der Allerbarmer. Er hat den Koran gelehrt. Er hat den Menschen erschaffen. Er hat ihn die klare Rede gelehrt.“ Dann zählt sie Gabe um Gabe auf – Sonne und Mond, Pflanzen und Bäume, die Waage der Gerechtigkeit, die Früchte, die zwei Meere, die Perlen, die Schiffe – und richtet nach jeder Gruppe dieselbe Frage an Menschen und Ǧinn: „Welche der Wohltaten eures Herrn wollt ihr beide denn leugnen?“ Einunddreißig Mal. Mittendrin die Vergänglichkeit: „Alles auf ihr ist vergänglich – es bleibt das Angesicht deines Herrn.“ Und am Ende vier Gärten für die, die vor dem Stehen vor ihrem Herrn Ehrfurcht haben.",
schluessel: {arab: "فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ", ueb: "Welche der Wohltaten eures Herrn wollt ihr beide denn leugnen?", ref: "55:13 (31-mal in der Sure)"},
kontext: ["Zur Einordnung ehrlich: Die Kairoer Ausgabe führt Ar-Raḥmān als medinensisch; viele Gelehrte sehen sie als mekkanisch. Für die mekkanische Sicht spricht der Sīra-Bericht, Ibn Masʿūd sei der Erste gewesen, der den Koran öffentlich an der Kaaba laut rezitierte – mit dieser Sure – und dafür von den Quraisch geschlagen wurde (Ibn Isḥāq; nicht in den Sahih-Werken). Beides wird vertreten.",
"Die Sure spricht ausdrücklich zwei Zuhörergruppen an: Menschen und Ǧinn (‚ihr beide‘, das arabische Dual). Sie nennt die Erschaffung beider (55:14–15: der Mensch aus Ton, die Ǧinn aus rauchlosem Feuer) und fordert beide heraus (55:33). Das verbindet sie mit Lektion 40 (Al-Ǧinn).",
"Dschābir berichtet: Der Prophet ﷺ trug seinen Gefährten Ar-Raḥmān vor, von Anfang bis Ende, und sie schwiegen. Da sagte er: „Ich habe sie den Ǧinn in der Nacht der Ǧinn vorgetragen, und sie antworteten besser als ihr. Jedes Mal, wenn ich zu ‚Welche der Wohltaten eures Herrn wollt ihr beide leugnen?‘ kam, sagten sie: Nichts von Deinen Wohltaten, unser Herr, leugnen wir – Dir gebührt das Lob“ (Sunan at-Tirmidhī, Nr. 3291)."],
asbab: ["Kein Einzelanlass sahih überliefert. Vgl. den Sīra-Bericht über Ibn Masʿūds öffentliche Rezitation (nicht in den Sahih-Werken) und den Ǧinn-Hadith bei at-Tirmidhī."],
begriffe: [
 {arab: "الرَّحْمَٰن", tr: "ar-Raḥmān", wurzel: "r-ḥ-m", erkl: "Der Allerbarmer – der Name, dessen Barmherzigkeit alles umfasst (vgl. Lektion 5). Die Sure beginnt mit Ihm und zeigt dann, wie diese Barmherzigkeit aussieht: als Lehren, Erschaffen, Versorgen, Ordnen."},
 {arab: "الْبَيَان", tr: "al-bayān", wurzel: "b-y-n", erkl: "Die klare Rede / Ausdrucksfähigkeit (55:4) – die Fähigkeit, Gedanken in Worte zu fassen. Eine der größten Gaben an den Menschen; Allah nennt sie direkt nach dem Koran und der Erschaffung."},
 {arab: "الْمِيزَان", tr: "al-mīzān", wurzel: "w-z-n", erkl: "Die Waage (55:7–9) – Gleichgewicht im Kosmos und Gerechtigkeit unter Menschen. „Überschreitet nicht das Maß in der Waage … und schmälert die Waage nicht.“ Dreimal in drei Versen: Gerechtigkeit ist Teil der Schöpfungsordnung."},
 {arab: "آلَاء", tr: "ālāʾ", wurzel: "ʾ-l-y", erkl: "Wohltaten, Gnaden – Plural von ilā. Die Frage „Welche der ālāʾ …?“ zwingt zum Nachdenken: Jede einzelne Gabe kann man nicht leugnen, ohne sich selbst zu belügen."},
 {arab: "بَرْزَخ", tr: "barzach", wurzel: "b-r-z-ch", erkl: "Schranke (55:20) – zwischen den zwei Meeren, die sich treffen, aber nicht vermischen. Dasselbe Wort steht für die Zwischenwelt zwischen Tod und Auferstehung (23:100)."},
 {arab: "فَانٍ", tr: "fānin", wurzel: "f-n-y", erkl: "„Vergänglich“ (55:26): „Alles, was auf ihr ist, ist vergänglich, und es bleibt das Angesicht deines Herrn, des Besitzers der Majestät und der Ehre (dhū l-dschalāli wa-l-ikrām).“ Mitten zwischen den Gaben steht ihr Ende – damit du am Geber hängst, nicht an der Gabe."},
 {arab: "مَقَام رَبِّهِ", tr: "maqām rabbihī", wurzel: "q-w-m", erkl: "„Das Stehen vor seinem Herrn“ (55:46): „Für den, der das Stehen vor seinem Herrn fürchtet, gibt es zwei Gärten.“ Die Ehrfurcht vor der Abrechnung, die das Handeln heute lenkt."}
],
tafsir: [
 {vers: "Verse 1–25: Gaben der Schöpfung", text: "Die ersten vier Verse sind eine Reihenfolge der Gnade: Zuerst lehrte Allah den Koran, dann erschuf Er den Menschen. Ibn Kathīr: Die Rechtleitung ist die größte Gabe, darum steht sie vor der Erschaffung. Dann Sonne und Mond „nach Berechnung“, Sterne und Bäume, die sich niederwerfen, der erhobene Himmel und die Waage, die Erde mit Früchten, Palmen, Getreide und duftenden Pflanzen. Die Erschaffung von Mensch und Ǧinn, die zwei Ostpunkte und zwei Westpunkte (Sommer und Winter), die zwei Meere mit der Schranke, Perlen und Korallen, die Schiffe hoch wie Berge. Nach jeder Gruppe die Frage. As-Saʿdī: Die Wiederholung ist kein Schmuck, sondern Pädagogik – nach jeder Gabe musst du innehalten und antworten."},
 {vers: "Verse 26–45: Vergänglichkeit und Abrechnung", text: "„Alles auf ihr ist vergänglich, und es bleibt das Angesicht deines Herrn.“ Vers 29: „Ihn bittet, wer in den Himmeln und auf der Erde ist; jeden Tag ist Er mit einer Angelegenheit befasst.“ Vers 31: „Wir werden Uns euch widmen, ihr beiden Gewichtigen“ (Menschen und Ǧinn) – die Abrechnung kommt. Vers 33 fordert heraus: „Wenn ihr die Grenzen der Himmel und der Erde durchdringen könnt, dann durchdringt sie – ihr könnt es nur mit Macht (sulṭān).“ Dann der Tag, an dem der Himmel sich spaltet und rot wird wie Salböl, an dem die Verbrecher an ihren Merkmalen erkannt und an Stirnlocken und Füßen gepackt werden. Selbst hier die Frage nach den Wohltaten: Auch die Warnung ist eine Wohltat, weil sie rechtzeitig kommt."},
 {vers: "Verse 46–78: Die vier Gärten", text: "„Für den, der das Stehen vor seinem Herrn fürchtet, gibt es zwei Gärten“ – mit Ästen, Quellen, Früchten in Paaren, Ruhebetten aus Brokat, Gefährtinnen „mit gesenkten Blicken“, „als wären sie Rubine und Korallen“. Vers 60: „Ist der Lohn für das Gute (iḥsān) etwas anderes als das Gute?“ Dann zwei weitere Gärten darunter (55:62), für die nächste Stufe der Gläubigen – Al-Qurṭubī und andere deuten: zwei Gärten für die Vordersten, zwei für die Leute der Rechten (vgl. Al-Wāqiʿa). Der Hadith bestätigt die Stufen: „Zwei Gärten aus Silber, ihre Gefäße und was darin ist, und zwei Gärten aus Gold …“ (Sahih al-Buchari, Nr. 4878; Sahih Muslim, Nr. 180). Der Schlussvers kehrt zum Namen zurück: „Segensreich ist der Name deines Herrn, des Besitzers der Majestät und der Ehre.“"}
],
ahadith: [
 {text: "Der Prophet ﷺ trug den Gefährten Ar-Raḥmān vor; sie schwiegen. „Ich habe sie den Ǧinn vorgetragen, und sie antworteten besser als ihr: Bei jedem ‚Welche der Wohltaten …‘ sagten sie: Nichts von Deinen Wohltaten, unser Herr, leugnen wir – Dir gebührt das Lob.“", quelle: "Sunan at-Tirmidhī, Nr. 3291; von al-Albānī als gut eingestuft"},
 {text: "„Zwei Gärten aus Silber, ihre Gefäße und was darin ist; und zwei Gärten aus Gold, ihre Gefäße und was darin ist …“ – zu 55:46 und 55:62.", quelle: "Sahih al-Buchari, Nr. 4878; Sahih Muslim, Nr. 180"},
 {text: "„Haltet euch an (die Anrufung) ‚Yā dhā l-dschalāli wa-l-ikrām‘ (O Besitzer der Majestät und der Ehre).“ – der Name aus 55:27 und 55:78.", quelle: "Sunan at-Tirmidhī, Nr. 3525; sahih"}
],
hanafi: null,
umsetzung: [
 "Lies oder höre die Sure und antworte wie die Ǧinn: Nach jedem Refrain leise „lā bi-schaiʾin min niʿamika rabbanā nukadhdhib, fa-laka l-ḥamd“ – so wird aus Zuhören ein Gespräch.",
 "Schreib deine eigene ‚Ar-Raḥmān-Liste‘: Zehn Gaben aus deinem Leben, und nach jeder die Frage: Welche davon könnte ich leugnen?",
 "Achte die Waage (55:8–9) im Alltag: ehrliche Preise, korrekte Arbeitszeit, faire Bewertungen – Gerechtigkeit im Kleinen ist Teil der Schöpfungsordnung.",
 "Nutze im Bittgebet den Namen aus 55:27: „Yā dhā l-dschalāli wa-l-ikrām“ – der Prophet ﷺ empfahl, ihn oft zu sprechen."
]
},

// ───────────────────────── Lektion 98: Al-Insān ─────────────────────────
{
sure: 76, offb: 98, name: "Al-Insān", arab: "سُورَةُ الْإِنْسَانِ", de: "Der Mensch", verse: 31, ort: "Medina",
zeit: "Die Kairoer Ausgabe zählt sie als medinensisch; viele Gelehrte halten sie für mekkanisch – beides wird vertreten. Auch Ad-Dahr (Die Zeit) genannt",
kurz: "Eine Sure über den Menschen von seinem Nichts bis zu seinem Ziel. Sie beginnt mit einer Frage, die jeden still macht: „Kam nicht über den Menschen eine Zeitspanne, in der er nichts Erwähnenswertes war?“ Dann: aus einem gemischten Tropfen erschaffen, mit Gehör und Blick versehen, der Weg gezeigt – „sei er dankbar oder undankbar“. Den größten Raum nehmen die Frommen (al-abrār) ein, und ihr Bild ist von stiller Größe: Sie erfüllen ihre Gelübde, fürchten einen Tag, dessen Übel sich ausbreitet, und „sie geben Speise, obwohl sie sie selbst lieben, dem Armen, der Waise und dem Gefangenen: Wir speisen euch nur um Allahs Angesicht willen; wir wollen von euch weder Lohn noch Dank.“ Der Prophet ﷺ rezitierte diese Sure regelmäßig am Freitagmorgen im Fadschr-Gebet.",
schluessel: {arab: "إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ اللَّهِ لَا نُرِيدُ مِنكُمْ جَزَاءً وَلَا شُكُورًا", ueb: "Wir speisen euch nur um Allahs Angesicht willen. Wir wollen von euch weder Lohn noch Dank.", ref: "76:9"},
kontext: ["Zur Einordnung ehrlich: Die Kairoer Ausgabe führt Al-Insān als medinensisch, viele Mufassirūn als mekkanisch. Die Erwähnung des Gefangenen (76:8) wird manchmal als Hinweis auf Medina gelesen, wo es nach Badr Gefangene gab; andere sagen, Gefangene gab es auch in Mekka.",
"In manchen Tafsir-Werken (u. a. bei al-Wāḥidī) steht eine Geschichte, nach der ʿAlī, Fāṭima und ihre Diener drei Tage hintereinander ihr Essen einem Armen, einer Waise und einem Gefangenen gaben und die Verse darüber herabkamen. Ehrlich gesagt: Die Hadith-Kritiker, u. a. Ibn al-Dschauzī, stufen diese Überlieferung als nicht authentisch ein. Die Verse beschreiben einen Typus, keinen Einzelfall – und ʿAlī und Fāṭima gehören ohne Zweifel zu denen, auf die sie passen.",
"Abū Huraira berichtet: Der Prophet ﷺ rezitierte am Freitag im Fadschr-Gebet „Alif Lām Mīm, Tanzīl“ (As-Sadschda) und „Hal atā ʿalā l-insān“ (diese Sure) (Sahih al-Buchari, Nr. 891; Sahih Muslim, Nr. 880). Die Gelehrten erklären: Beide Suren erzählen von der Erschaffung des Menschen, seiner Prüfung und seinem Ende – passend zum Freitag, dem Tag, an dem Ādam erschaffen wurde und an dem die Stunde anbrechen wird."],
asbab: ["Kein Einzelanlass sahih gesichert. Die verbreitete Geschichte über ʿAlī und Fāṭima als Anlass von 76:8–9 wird von den Hadith-Kritikern als nicht authentisch eingestuft."],
begriffe: [
 {arab: "هَلْ أَتَىٰ", tr: "hal atā", wurzel: "ʾ-t-y", erkl: "„Kam nicht …?“ – eine Frage, die eine Feststellung ist: Ja, es gab eine Zeit, in der du nichts warst. Der Anfang aller Demut."},
 {arab: "أَمْشَاج", tr: "amschādsch", wurzel: "m-sch-dsch", erkl: "„Gemischt“ (76:2) – der Tropfen aus der Vereinigung von Mann und Frau. Aus einer Mischung erschaffen, „um ihn zu prüfen“ – das Leben ist von Anfang an Prüfung."},
 {arab: "شَاكِرًا وَإِمَّا كَفُورًا", tr: "schākiran wa-immā kafūrā", wurzel: "sch-k-r / k-f-r", erkl: "„Sei er dankbar oder undankbar“ (76:3) – Allah hat den Weg gezeigt; die Wahl liegt beim Menschen. Dankbarkeit und Undank sind die zwei Grundhaltungen des Lebens (vgl. Lektion 14, Al-ʿĀdiyāt)."},
 {arab: "الْأَبْرَار", tr: "al-abrār", wurzel: "b-r-r", erkl: "Die Frommen – Plural von barr: die viel Gutes tun. Von derselben Wurzel wie birr (Güte, vgl. Lektion 91). Die Sure widmet ihnen den größten Teil."},
 {arab: "يُوفُونَ بِالنَّذْر", tr: "yūfūna bi-n-nadhr", wurzel: "w-f-y / n-dh-r", erkl: "„Sie erfüllen das Gelübde“ (76:7) – was sie Allah versprochen haben, halten sie. Wer schon freiwillige Versprechen hält, hält die Pflichten erst recht."},
 {arab: "عَلَىٰ حُبِّهِ", tr: "ʿalā ḥubbihī", wurzel: "ḥ-b-b", erkl: "„Obwohl sie es lieben“ (76:8) – sie geben nicht Überschuss, sondern etwas, das sie selbst gern hätten. Andere deuten: ‚aus Liebe zu Ihm (Allah)‘. Beide Bedeutungen ergänzen sich."},
 {arab: "سَلْسَبِيل", tr: "salsabīl", wurzel: "–", erkl: "Eine Quelle im Paradies (76:18), deren Name ‚leicht fließend‘ bedeutet. Die Sure beschreibt Getränke aus Kampfer und Ingwer, Silbergefäße, grüne Seide – Bilder einer Welt, deren Wirklichkeit unsere Sprache übersteigt."}
],
tafsir: [
 {vers: "Verse 1–4: Woher der Mensch kommt", text: "Die Eröffnungsfrage, die Erschaffung aus einem gemischten Tropfen, Gehör und Blick, der gezeigte Weg. Ibn Kathīr: Der Mensch, der heute stolz ist, war einst nicht einmal erwähnenswert. Vers 4 nennt das Ende der Undankbaren: Ketten, Fesseln und loderndes Feuer."},
 {vers: "Verse 5–12: Die Frommen und ihr Geben", text: "Die abrār trinken aus einem Becher, gemischt mit Kampfer, aus einer Quelle, die sie sprudeln lassen, wo sie wollen. Warum? Vers 7–10: Sie erfüllen Gelübde, fürchten den Tag, geben Speise trotz eigener Liebe dazu – dem Armen, der Waise, dem Gefangenen – und sagen (in ihren Herzen, wie die Gelehrten erklären): „Wir speisen euch nur um Allahs Angesicht willen; wir wollen von euch weder Lohn noch Dank.“ Al-Qurṭubī: Bemerkenswert ist der Gefangene – damals oft ein Nichtmuslim, ein Kriegsgegner. Die Frommen speisen sogar ihn. Das passt zu 47:4 (Brennpunkt): Gefangene werden nicht misshandelt, sondern versorgt. Vers 11–12: Allah bewahrt sie vor dem Übel jenes Tages und „vergilt ihnen dafür, dass sie standhaft waren, mit einem Garten und mit Seide“."},
 {vers: "Verse 13–22: Das Paradies", text: "Ruhebetten, weder Sonnenglut noch bittere Kälte, tief hängende Früchte, Gefäße aus Silber und Kristall, Ingwer und die Quelle Salsabīl, ewig junge Diener „wie verstreute Perlen“. Vers 20: „Wenn du dorthin schaust, siehst du Wonne und großes Königreich.“ Vers 22: „Dies ist euer Lohn, und euer Bemühen wurde gedankt.“ As-Saʿdī: Wer im Diesseits keinen Dank von Menschen wollte (76:9), dem dankt Allah selbst."},
 {vers: "Verse 23–31: Standhaftigkeit und Gedenken", text: "Die Schlussverse wenden sich an den Propheten ﷺ: „Wir haben dir den Koran wahrhaftig schrittweise herabgesandt“ (vgl. 25:32, Lektion 42). „So sei standhaft gegenüber dem Urteil deines Herrn und gehorche keinem Sünder und Undankbaren unter ihnen. Und gedenke des Namens deines Herrn morgens und abends, und in der Nacht wirf dich vor Ihm nieder und preise Ihn eine lange Nacht.“ Vers 27 nennt das Grundproblem: „Sie lieben das Eilige und lassen hinter sich einen schweren Tag.“ Vers 29–30: „Dies ist eine Erinnerung; wer will, nimmt einen Weg zu seinem Herrn – doch ihr wollt nur, wenn Allah will.“"}
],
ahadith: [
 {text: "Der Prophet ﷺ rezitierte am Freitag im Fadschr-Gebet As-Sadschda und Al-Insān.", quelle: "Sahih al-Buchari, Nr. 891; Sahih Muslim, Nr. 880"},
 {text: "„Wer gelobt, Allah zu gehorchen, der soll Ihm gehorchen; und wer gelobt, Ihm ungehorsam zu sein, der soll Ihm nicht ungehorsam sein.“ – zu 76:7.", quelle: "Sahih al-Buchari, Nr. 6696"},
 {text: "„Befreit den Gefangenen, speist den Hungrigen und besucht den Kranken.“", quelle: "Sahih al-Buchari, Nr. 3046"},
 {text: "„Die Werke werden nur nach den Absichten (beurteilt).“ – die Haltung von 76:9.", quelle: "Sahih al-Buchari, Nr. 1; Sahih Muslim, Nr. 1907"}
],
hanafi: "Zu 76:7 (Gelübde): Nach hanafitischer Schule ist ein Gelübde (nadhr), das sich auf eine Gottesdienst-Handlung richtet, die ihrer Art nach eine Pflicht hat (z. B. Fasten, Gebet, Spende), verbindlich (wādschib) zu erfüllen. Ein Gelübde zu einer Sünde ist ungültig und darf nicht erfüllt werden; nach der Schule ist dafür die Sühne eines Eides (kaffārat al-yamīn) zu leisten. Ein bedingtes Gelübde („Wenn ich gesund werde, faste ich drei Tage“) wird mit Eintritt der Bedingung verbindlich. Praktisch: Versprich Allah nichts leichtfertig – und was du versprochen hast, halte.",
umsetzung: [
 "Bete freitags in der Moschee Fadschr und hör bewusst auf die Rezitation – wenn der Imam der Sunna folgt, hörst du genau diese Sure.",
 "Gib diese Woche etwas, das du selbst gern behalten würdest (76:8) – nicht das Übrige, sondern das Geliebte.",
 "Gib einmal ohne jeden Wunsch nach Dank: anonym, ohne Rückmeldung zu erwarten, ohne es zu erzählen (76:9).",
 "Prüfe deine Gelübde: Hast du Allah etwas versprochen und nicht gehalten? Hol es jetzt nach."
]
},

// ───────────────────────── Lektion 99: Aṭ-Ṭalāq ─────────────────────────
{
sure: 65, offb: 99, name: "Aṭ-Ṭalāq", arab: "سُورَةُ الطَّلَاقِ", de: "Die Scheidung", verse: 12, ort: "Medina",
zeit: "Medina, mittlere Zeit – Anlass war eine Scheidung, die nicht zum richtigen Zeitpunkt ausgesprochen wurde",
kurz: "Eine Sure über das Scheitern einer Ehe – und darüber, wie man auch dann gottesfürchtig, gerecht und würdevoll bleibt. Sie regelt den richtigen Zeitpunkt der Scheidung, die Wartezeit (ʿidda), das Wohnrecht der Frau, den Unterhalt und das Stillen. Und mitten in diesen Rechtsregeln stehen die vielleicht hoffnungsvollsten Verse des Korans über Gottvertrauen: „Wer Allah fürchtet, dem schafft Er einen Ausweg und versorgt ihn, von wo er es nicht erwartet. Und wer auf Allah vertraut, dem genügt Er.“ Die Botschaft: Gerade in der Krise, gerade wenn die Familie zerbricht, ist Taqwā der Weg hinaus.",
schluessel: {arab: "وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ", ueb: "Und wer Allah fürchtet, dem schafft Er einen Ausweg und versorgt ihn, von wo er es nicht erwartet.", ref: "65:2–3"},
kontext: ["ʿAbdullāh ibn ʿUmar hatte seine Frau während ihrer Menstruation geschieden. Sein Vater ʿUmar fragte den Propheten ﷺ, und dieser wurde zornig: Er solle sie zurücknehmen, bis sie rein werde, dann wieder menstruiere, dann wieder rein werde – und danach, wenn er will, sie scheiden, bevor er sie berührt. „Das ist die Wartezeit, nach der Allah befohlen hat, die Frauen zu scheiden“ (Sahih al-Buchari, Nr. 5251; Sahih Muslim, Nr. 1471). Der Prophet ﷺ las dazu den Anfang der Sure.",
"Warum ist der Zeitpunkt so wichtig? Eine Scheidung im Zorn, im falschen Moment, ohne Besinnung, ist das Gegenteil dessen, was die Sure will. Die Regeln bremsen: Wartezeit, Wohnen im selben Haus, die Möglichkeit der Rücknahme. Vers 1 sagt: „Du weißt nicht – vielleicht lässt Allah danach etwas Neues geschehen.“ Die Tür zur Versöhnung soll so lange wie möglich offen bleiben.",
"Die Sure hat einen bemerkenswerten Ton: Nach fast jeder Rechtsregel folgt ein Satz über Taqwā, Vertrauen und Erleichterung. Das zeigt, wie der Koran Recht versteht – nicht als kalte Paragraphen, sondern als Weg, auf dem man Allah begegnet, gerade wenn es schwer ist."],
asbab: [
 {text: "65:1: Ibn ʿUmar schied seine Frau während der Menstruation; der Prophet ﷺ befahl ihm, sie zurückzunehmen und den richtigen Zeitpunkt abzuwarten.", quelle: "Sahih al-Buchari, Nr. 5251; Sahih Muslim, Nr. 1471"},
 {text: "65:4 (Wartezeit der Schwangeren endet mit der Geburt): Subaiʿa al-Aslamiyya gebar kurz nach dem Tod ihres Mannes; der Prophet ﷺ erklärte ihr, dass sie nach der Geburt wieder heiraten darf.", quelle: "Sahih al-Buchari, Nr. 5318–5319; Sahih Muslim, Nr. 1484"}
],
begriffe: [
 {arab: "طَلَاق", tr: "ṭalāq", wurzel: "ṭ-l-q", erkl: "Scheidung – wörtlich ‚Freilassen, Lösen‘. Im Islam erlaubt, aber nach dem Hadith-Sinn das Erlaubte, das Allah am wenigsten liebt (die bekannte Überlieferung dazu, Abū Dāwūd, Nr. 2178, ist in ihrer Echtheit umstritten; der Sinn wird von den Gelehrten geteilt)."},
 {arab: "عِدَّة", tr: "ʿidda", wurzel: "ʿ-d-d", erkl: "Die Wartezeit nach Scheidung oder Tod des Mannes – „zählt die Wartezeit genau“ (65:1). Sie schützt die Klarheit der Abstammung, gibt Zeit zur Besinnung und hält die Tür zur Versöhnung offen."},
 {arab: "حُدُود اللَّه", tr: "ḥudūd Allāh", wurzel: "ḥ-d-d", erkl: "„Die Grenzen Allahs“ (65:1) – hier die Regeln der Scheidung. „Wer Allahs Grenzen überschreitet, hat sich selbst Unrecht getan.“ Unfaire Scheidung schadet am Ende dem, der sie betreibt."},
 {arab: "مَخْرَج", tr: "machradsch", wurzel: "ch-r-dsch", erkl: "Ausweg (65:2) – Allah schafft dem Gottesfürchtigen einen Ausweg aus jeder Enge. Nicht unbedingt den, den er sich vorstellt, aber einen echten."},
 {arab: "حَسْبُهُ", tr: "ḥasbuhū", wurzel: "ḥ-s-b", erkl: "„Er genügt ihm“ (65:3) – wer auf Allah vertraut, für den ist Allah genug. Daher der Ausruf ḥasbunallāhu wa-niʿma l-wakīl (3:173)."},
 {arab: "يُسْرًا", tr: "yusran", wurzel: "y-s-r", erkl: "Erleichterung – 65:4: „Wer Allah fürchtet, dem schafft Er in seiner Angelegenheit Erleichterung.“ 65:7: „Allah wird nach Erschwernis Erleichterung schaffen.“ Vgl. Lektion 12 (Asch-Scharḥ)."},
 {arab: "بِمَعْرُوف", tr: "bi-maʿrūf", wurzel: "ʿ-r-f", erkl: "„Auf rechtliche, anständige Weise“ (65:2, 65:6) – behaltet sie in Güte oder trennt euch in Güte. Auch die Trennung hat Würde."}
],
tafsir: [
 {vers: "Verse 1–3: Der richtige Zeitpunkt und das Vertrauen", text: "„O Prophet, wenn ihr Frauen scheidet, dann scheidet sie zu ihrer Wartezeit und zählt die Wartezeit genau.“ – mit der Sunna-Erklärung aus dem Ibn-ʿUmar-Hadith: in einer Reinheitszeit, in der kein Geschlechtsverkehr stattfand. „Weist sie nicht aus ihren Häusern aus, und sie sollen nicht hinausgehen“ – während der Wartezeit bleibt die Frau in ihrem Zuhause. Vers 2: Am Ende der Frist entweder in Güte behalten oder in Güte trennen – mit zwei gerechten Zeugen. Dann die Verheißung: „Wer Allah fürchtet, dem schafft Er einen Ausweg und versorgt ihn, von wo er es nicht erwartet. Und wer auf Allah vertraut, dem genügt Er.“ Ibn Kathīr: Wer in der Scheidung gerecht bleibt, obwohl es ihn etwas kostet, dem ersetzt Allah es."},
 {vers: "Verse 4–7: Wartezeiten, Wohnung, Unterhalt", text: "Wartezeit für Frauen ohne Menstruation (wegen Alters oder Jugend): drei Monate. Für Schwangere: bis zur Geburt (vgl. Subaiʿa). Vers 6: „Lasst sie wohnen, wo ihr wohnt, nach euren Mitteln, und fügt ihnen keinen Schaden zu, um sie zu bedrängen.“ Schwangere erhalten Unterhalt bis zur Geburt; stillt die Frau das gemeinsame Kind, bekommt sie dafür Lohn – „und beratet euch untereinander in rechtlicher Weise“. Vers 7: „Wer reichlich hat, soll von seinem Reichtum ausgeben, und wem die Versorgung bemessen ist, der gebe von dem, was Allah ihm gegeben hat. Allah erlegt keiner Seele mehr auf, als Er ihr gegeben hat. Allah wird nach Erschwernis Erleichterung schaffen.“"},
 {vers: "Verse 8–12: Warnung und Licht", text: "Wie viele Städte, die sich gegen Allahs Befehl auflehnten, wurden zur Rechenschaft gezogen! Vers 10–11: Allah hat eine Ermahnung herabgesandt – einen Gesandten, der klare Verse vorträgt, „um die Gläubigen aus den Finsternissen ins Licht zu führen“. Vers 12 weitet den Blick: Allah erschuf sieben Himmel und von der Erde ebenso viele, „damit ihr wisst, dass Allah zu allem fähig ist und alles mit Wissen umfasst“. As-Saʿdī: Eine Sure über Familienrecht endet im Kosmos – weil derselbe Allah, der die Himmel ordnet, auch die Ordnung deiner Familie geregelt hat."}
],
ahadith: [
 {text: "Ibn ʿUmar schied seine Frau während der Menstruation. Der Prophet ﷺ: „Befiehl ihm, sie zurückzunehmen … dann, wenn er will, soll er sie in der Reinheitszeit scheiden, bevor er sie berührt. Das ist die Wartezeit, nach der Allah befohlen hat, die Frauen zu scheiden.“", quelle: "Sahih al-Buchari, Nr. 5251; Sahih Muslim, Nr. 1471"},
 {text: "Subaiʿa al-Aslamiyya: Nach der Geburt ihres Kindes, kurz nach dem Tod ihres Mannes, erklärte ihr der Prophet ﷺ, dass ihre Wartezeit beendet ist – zu 65:4.", quelle: "Sahih al-Buchari, Nr. 5319; Sahih Muslim, Nr. 1484"},
 {text: "„Würdet ihr auf Allah vertrauen, wie es Ihm gebührt, würde Er euch versorgen, wie Er die Vögel versorgt: Sie gehen morgens hungrig hinaus und kehren abends satt zurück.“ – zu 65:3.", quelle: "Sunan at-Tirmidhī, Nr. 2344; sahih"}
],
hanafi: "Aṭ-Ṭalāq ist ein Kernkapitel des hanafitischen Familienrechts: (1) Die Sunna-Form der Scheidung (ṭalāq as-sunna): ein einziger Ausspruch in einer Reinheitszeit ohne vorherigen Verkehr – danach Abwarten der Wartezeit, in der die Rücknahme möglich ist. Drei Scheidungen auf einmal auszusprechen oder in der Menstruation zu scheiden, ist nach der Schule bidʿa und sündhaft – aber sie wird trotzdem wirksam (drei gelten als drei). (2) Wartezeit (ʿidda): Hanafitisch bedeutet qurūʾ (2:228) drei Menstruationen (nicht drei Reinheitszeiten wie bei den Schāfiʿiten). (3) Unterhalt und Wohnung: Nach der hanafitischen Schule hat jede geschiedene Frau während der Wartezeit Anspruch auf Wohnung UND Unterhalt (nafaqa) – auch bei endgültiger Scheidung. Die Schule folgt hier ʿUmar, der den abweichenden Bericht der Fāṭima bint Qais (Sahih Muslim, Nr. 1480) nicht als Grundlage nahm. (4) Zeugen bei der Scheidung (65:2) sind nach der Schule empfohlen, aber keine Gültigkeitsbedingung. In konkreten Fällen: immer einen qualifizierten Gelehrten fragen – Scheidungsfragen sind zu ernst für Selbstauslegung.",
umsetzung: [
 "Lerne 65:2–3 auswendig: wa-man yattaqi llāha yadschʿal lahū machradschā – und sprich sie in jeder Krise, nicht nur in Familienkrisen.",
 "Wenn du verheiratet bist: Vereinbare mit dir selbst, nie im Zorn das Wort ‚Scheidung‘ auszusprechen – die Sure baut absichtlich Bremsen ein; bau dir deine eigene.",
 "Wenn jemand in deinem Umfeld eine Trennung erlebt: Erinnere an 65:2 (trennen in Güte, ohne Schaden) und an 65:7 (nach Erschwernis Erleichterung).",
 "Übe Vertrauen wie die Vögel (Tirmidhī 2344): Tu deinen Teil – geh morgens los – und überlass Allah das Ergebnis."
]
},

// ───────────────────────── Lektion 100: Al-Bayyina ─────────────────────────
{
sure: 98, offb: 100, name: "Al-Bayyina", arab: "سُورَةُ الْبَيِّنَةِ", de: "Der klare Beweis", verse: 8, ort: "Medina",
zeit: "Medina – nach den meisten Gelehrten medinensisch (manche sagen mekkanisch); der Prophet ﷺ trug sie in Medina auf Allahs Befehl Ubayy ibn Kaʿb vor",
kurz: "Acht Verse, die die ganze Religion in einen Satz fassen: „Ihnen wurde nur befohlen, Allah zu dienen, aufrichtig Ihm gegenüber in der Religion, als Ḥunafāʾ (dem Wahren zugeneigt), das Gebet zu verrichten und die Zakat zu entrichten – das ist die Religion des Richtigen.“ Die Sure erklärt, warum die Schriftbesitzer und Götzendiener auf einen klaren Beweis (al-bayyina) warteten – einen Gesandten mit reinen Blättern – und warum sie sich erst spalteten, als er kam. Am Ende stehen zwei Gruppen: die schlechtesten der Geschöpfe und die besten der Geschöpfe. Diese Sure hat eine besondere Ehre: Allah befahl dem Propheten ﷺ, sie Ubayy ibn Kaʿb vorzutragen – und nannte Ubayy dabei beim Namen. Ubayy weinte.",
schluessel: {arab: "وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ", ueb: "Und ihnen wurde nur befohlen, Allah zu dienen, aufrichtig Ihm gegenüber in der Religion, als Anhänger des rechten Glaubens.", ref: "98:5"},
kontext: ["Anas berichtet: Der Prophet ﷺ sagte zu Ubayy ibn Kaʿb: „Allah hat mir befohlen, dir ‚Lam yakuni lladhīna kafarū‘ vorzutragen.“ Ubayy fragte: „Hat Er mich bei meinem Namen genannt?“ – „Ja.“ Da weinte Ubayy (Sahih al-Buchari, Nr. 4959; Sahih Muslim, Nr. 799). Ubayy war einer der besten Koranrezitatoren der Gefährten. Die Gelehrten ziehen daraus mehrere Lehren: Demut des Propheten ﷺ, der einem Schüler vorträgt; die Ehre der Koranlehrer; und dass Allah Seine Diener persönlich kennt.",
"Die Sure beschreibt eine Situation, die du aus den Lektionen 39 und 92 kennst: Juden und Christen erwarteten einen Propheten – er war in ihren Schriften angekündigt (vgl. 7:157). Als er kam, spaltete die Frage, ob er es sei, die Schriftbesitzer: Manche glaubten, viele lehnten ab. Vers 4: „Die Schriftbesitzer haben sich erst gespalten, nachdem der klare Beweis zu ihnen gekommen war.“ Nicht Unklarheit war das Problem, sondern die Annahme.",
"Vers 5 ist der Kern: Die Botschaft aller Propheten war im Grunde immer dieselbe – aufrichtige Anbetung, Gebet, Zakat. Der Islam bringt keine fremde Religion, sondern die ursprüngliche, die ‚Religion des Richtigen‘ (dīn al-qayyima)."],
asbab: ["Kein gesicherter Einzelanlass für die Herabsendung. Gesichert ist der Bericht, dass Allah dem Propheten ﷺ befahl, die Sure Ubayy ibn Kaʿb vorzutragen (Sahih al-Buchari, Nr. 4959; Sahih Muslim, Nr. 799)."],
begriffe: [
 {arab: "الْبَيِّنَة", tr: "al-bayyina", wurzel: "b-y-n", erkl: "Der klare Beweis – nach Vers 2 der Gesandte selbst, „der gereinigte Blätter vorträgt“. Der Prophet ﷺ in Person war der Beweis: sein Charakter, sein Leben, sein Koran."},
 {arab: "مُنفَكِّين", tr: "munfakkīn", wurzel: "f-k-k", erkl: "„Ablassend, sich lösend“ (98:1) – die Ungläubigen „ließen nicht ab (von ihrem Zustand), bis der klare Beweis zu ihnen kam“. Erst der Gesandte setzte eine Entscheidung in Gang."},
 {arab: "صُحُفًا مُّطَهَّرَة", tr: "ṣuḥufan muṭahhara", wurzel: "ṭ-h-r", erkl: "„Gereinigte Blätter“ (98:2) – der Koran, rein von Fälschung und Widerspruch. In ihnen „wertvolle Schriften“ (kutub qayyima): das Beste der früheren Botschaften."},
 {arab: "مُخْلِصِين", tr: "muchliṣīn", wurzel: "ch-l-ṣ", erkl: "„Aufrichtig“ (98:5) – mit reiner Absicht, nur für Allah. Dieselbe Wurzel wie Ichlāṣ (Lektion 22). Ohne Ichlāṣ ist jede Tat leer."},
 {arab: "حُنَفَاء", tr: "ḥunafāʾ", wurzel: "ḥ-n-f", erkl: "Plural von ḥanīf – dem Wahren zugewandt, von allem Falschen abgewandt. So beschreibt der Koran Ibrāhīm. Der Islam ist die Religion Ibrāhīms, des Ḥanīf."},
 {arab: "دِين الْقَيِّمَة", tr: "dīn al-qayyima", wurzel: "q-w-m", erkl: "„Die Religion des Richtigen / Beständigen“ (98:5) – dieselbe Wurzel wie mustaqīm (der gerade Weg). Die aufrechte, nicht verbogene Religion."},
 {arab: "خَيْر الْبَرِيَّة", tr: "chair al-bariyya", wurzel: "b-r-ʾ", erkl: "„Die Besten der Geschöpfe“ (98:7) – „die glauben und rechtschaffene Werke tun“. Nicht Abstammung, nicht Reichtum, nicht Volk: Iman und gute Taten machen den Rang."}
],
tafsir: [
 {vers: "Verse 1–4: Warten und Spaltung", text: "„Die Ungläubigen unter den Schriftbesitzern und den Götzendienern ließen nicht ab, bis der klare Beweis zu ihnen kam: ein Gesandter von Allah, der gereinigte Blätter vorträgt, in denen wertvolle Schriften sind.“ Ibn Kathīr: Sie alle warteten auf etwas – die Schriftbesitzer auf den angekündigten Propheten, die Götzendiener auf einen Beweis. Als er kam, zeigte sich, wer wirklich nach Wahrheit gesucht hatte. Vers 4: Die Spaltung kam nicht aus Mangel an Klarheit, sondern danach."},
 {vers: "Vers 5: Die ganze Religion in einem Satz", text: "„Und ihnen wurde nur befohlen, Allah zu dienen, aufrichtig Ihm gegenüber in der Religion, als Ḥunafāʾ, das Gebet zu verrichten und die Zakat zu entrichten – das ist die Religion des Richtigen.“ As-Saʿdī: Vier Bausteine – Anbetung, Aufrichtigkeit, Gebet, Zakat. Wer diese vier hat, hat das Fundament. Die Gelehrten nutzen diesen Vers als einen der Belege dafür, dass die Absicht (niyya) in der Anbetung zentral ist – dazu der erste Hadith im Sahih al-Buchari: „Die Werke werden nur nach den Absichten beurteilt.“"},
 {vers: "Verse 6–8: Die Schlechtesten und die Besten", text: "Die, die nach dem klaren Beweis ungläubig blieben, sind „die schlechtesten der Geschöpfe“. „Diejenigen aber, die glauben und rechtschaffene Werke tun, das sind die besten der Geschöpfe.“ Ihr Lohn: Gärten Edens, durcheilt von Bächen, ewig – „Allah hat Wohlgefallen an ihnen, und sie haben Wohlgefallen an Ihm“ (vgl. 89:28, Lektion 10: rāḍiya marḍiyya). Der Schlusssatz: „Das ist für den, der seinen Herrn fürchtet.“ Al-Qurṭubī: Der höchste Lohn ist nicht der Garten, sondern das gegenseitige Wohlgefallen."}
],
ahadith: [
 {text: "Der Prophet ﷺ zu Ubayy ibn Kaʿb: „Allah hat mir befohlen, dir ‚Lam yakuni lladhīna kafarū‘ vorzutragen.“ – „Hat Er mich bei meinem Namen genannt?“ – „Ja.“ Da weinte Ubayy.", quelle: "Sahih al-Buchari, Nr. 4959; Sahih Muslim, Nr. 799"},
 {text: "„Die Werke werden nur nach den Absichten beurteilt, und jedem Menschen gehört nur, was er beabsichtigt hat.“", quelle: "Sahih al-Buchari, Nr. 1; Sahih Muslim, Nr. 1907"},
 {text: "„Der Islam ist auf fünf (Säulen) gebaut …“ – darunter Gebet und Zakat, die 98:5 ausdrücklich nennt.", quelle: "Sahih al-Buchari, Nr. 8; Sahih Muslim, Nr. 16"}
],
hanafi: "Zu 98:5 und der Absicht (niyya): Andere Schulen leiten aus diesem Vers ab, dass die Absicht für jede Gottesdienst-Handlung – auch für die Gebetswaschung (Wuḍūʾ) – eine Gültigkeitsbedingung ist. Die hanafitische Schule unterscheidet: Beim Gebet, Fasten, bei Zakat und Ḥaddsch ist die Absicht Pflicht. Beim Wuḍūʾ dagegen ist sie Sunna, nicht Bedingung – denn das Wuḍūʾ ist ein Mittel zum Gebet, keine eigenständige Anbetung; ein Wuḍūʾ ohne Absicht ist gültig, bringt aber keinen Lohn. Praktisch: Fass trotzdem immer die Absicht – sie verwandelt eine Waschung in Anbetung.",
umsetzung: [
 "Prüfe vor jedem Gebet kurz deine Absicht: Für wen tue ich das? Ein Atemzug Ichlāṣ vor dem Takbīr verändert das ganze Gebet.",
 "Nimm 98:5 als Checkliste: Anbetung, Aufrichtigkeit, Gebet, Zakat – wo bist du schwach? Hast du deine Zakat dieses Jahr korrekt berechnet?",
 "Ehre die Koranlehrer: Ubayy wurde von Allah beim Namen genannt, weil er den Koran trug. Bedank dich bei dem, der dir das Lesen beigebracht hat.",
 "Merke dir chair al-bariyya als Maßstab für Menschen: Glaube und gute Taten – nicht Herkunft, nicht Reichtum."
]
},

// ───────────────────────── Lektion 101: Al-Ḥaschr ─────────────────────────
{
sure: 59, offb: 101, name: "Al-Ḥaschr", arab: "سُورَةُ الْحَشْرِ", de: "Die Versammlung", verse: 24, ort: "Medina",
zeit: "Medina, 4 n. H. – nach der Vertreibung des jüdischen Stammes Banū n-Naḍīr; Ibn ʿAbbās nannte sie ‚Sure der Banū n-Naḍīr‘",
kurz: "Eine Sure aus einer konkreten politischen Krise – und mit einem der erhabensten Schlüsse des Korans. Der Stamm der Banū n-Naḍīr, mit den Muslimen vertraglich verbunden, hatte den Vertrag gebrochen; nach den Sīra-Berichten planten Einzelne von ihnen sogar ein Attentat auf den Propheten ﷺ. Nach einer Belagerung zogen sie ab. Die Sure deutet das Ereignis und regelt den Umgang mit der kampflosen Beute (fayʾ) – mit einem Grundsatz für jede Wirtschaftsordnung: Besitz soll nicht nur zwischen den Reichen kreisen. Dann ein unvergessliches Porträt: die Anṣār, die den Auswanderern alles teilten, „auch wenn sie selbst in Not waren“. Und am Ende: „Würden Wir diesen Koran auf einen Berg herabsenden, du sähest ihn demütig zerbersten aus Furcht vor Allah“ – gefolgt von den schönsten Namen Allahs in drei Versen.",
schluessel: {arab: "يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ", ueb: "O ihr, die ihr glaubt, fürchtet Allah, und jede Seele schaue, was sie für morgen vorausschickt.", ref: "59:18"},
kontext: ["Saʿīd ibn Dschubair fragte Ibn ʿAbbās nach Sure Al-Ḥaschr; er antwortete: „Sag: Sure der Banū n-Naḍīr“ (Sahih al-Buchari, Nr. 4882; Sahih Muslim, Nr. 3031). Die Banū n-Naḍīr waren ein jüdischer Stamm in Medina, mit dem der Prophet ﷺ einen Vertrag hatte. Nach den Sīra-Berichten brachen sie ihn; als die Muslime sie belagerten, zogen sie mit ihrer beweglichen Habe nach Ḫaibar und Syrien ab. Die Sure nennt das den ‚ersten Auszug‘ (awwal al-ḥaschr).",
"Wichtig für dein Verständnis, auch für Gespräche: Der Konflikt war ein politischer Vertragsbruch, nicht eine Verfolgung wegen der Religion. Andere jüdische Gruppen, die ihre Verträge hielten, blieben unbehelligt; der Koran gebietet ausdrücklich Gerechtigkeit gegenüber allen, die nicht kämpfen (60:8, Lektion 91). Vers 2 sagt über die Banū n-Naḍīr: „Sie meinten, ihre Festungen würden sie vor Allah schützen“ – die Sure deutet ihr Scheitern als Folge ihres Handelns.",
"Während der Belagerung ließ der Prophet ﷺ einige Palmen fällen; die Gegner warfen den Muslimen Zerstörung vor. Vers 5 antwortet: Was gefällt oder stehen gelassen wurde, geschah mit Allahs Erlaubnis (Sahih al-Buchari, Nr. 4884; Sahih Muslim, Nr. 1746). Die Gelehrten betonen: Das war eine militärische Einzelentscheidung in einer Belagerung, keine allgemeine Erlaubnis zur Umweltzerstörung – die allgemeine Regel bleibt das Verbot unnötiger Zerstörung (vgl. Abū Bakrs Anweisungen im Brennpunkt-Modul)."],
asbab: [
 {text: "Die Sure insgesamt: die Vertreibung der Banū n-Naḍīr – „Sag: Sure der Banū n-Naḍīr“.", quelle: "Sahih al-Buchari, Nr. 4882; Sahih Muslim, Nr. 3031"},
 {text: "59:5: das Fällen einzelner Palmen während der Belagerung.", quelle: "Sahih al-Buchari, Nr. 4884; Sahih Muslim, Nr. 1746"},
 {text: "59:9: Ein Anṣārī (nach den Berichten Abū Ṭalḥa) nahm einen hungrigen Gast auf, obwohl nur Essen für die Kinder da war; er und seine Frau löschten das Licht und taten so, als äßen sie mit, damit der Gast satt wurde. Der Prophet ﷺ sagte am Morgen: „Allah hat gestaunt (bzw. gelacht) über das, was ihr beide getan habt“ – und der Vers kam herab.", quelle: "Sahih al-Buchari, Nr. 3798; Sahih Muslim, Nr. 2054"}
],
begriffe: [
 {arab: "الْحَشْر", tr: "al-ḥaschr", wurzel: "ḥ-sch-r", erkl: "Die Versammlung / das Zusammentreiben – hier der Auszug der Banū n-Naḍīr; zugleich das Wort für die große Versammlung am Jüngsten Tag (yaum al-ḥaschr). Ein irdischer Auszug als Erinnerung an den letzten."},
 {arab: "فَاعْتَبِرُوا", tr: "fa-ʿtabirū", wurzel: "ʿ-b-r", erkl: "„So zieht eine Lehre daraus“ (59:2) – ʿibra: das Übergehen von einem Fall zur allgemeinen Lehre. Aus diesem Wort leiteten manche Gelehrte auch die Legitimität des Analogieschlusses (qiyās) ab."},
 {arab: "فَيْء", tr: "fayʾ", wurzel: "f-y-ʾ", erkl: "Besitz, der ohne Kampf an die Muslime fällt (59:6–7). Er wird nicht unter Kämpfern verteilt, sondern für Allgemeinwohl, Verwandte des Propheten ﷺ, Waisen, Arme und Reisende verwendet."},
 {arab: "دُولَة", tr: "dūla", wurzel: "d-w-l", erkl: "„Etwas, das (nur) im Kreis umläuft“ (59:7): „damit es nicht nur zwischen den Reichen unter euch umläuft“. Ein wirtschaftlicher Grundsatz des Korans: Reichtum soll fließen, nicht sich anhäufen."},
 {arab: "يُؤْثِرُونَ", tr: "yuʾthirūn", wurzel: "ʾ-th-r", erkl: "„Sie bevorzugen (andere vor sich selbst)“ (59:9) – īthār: die höchste Stufe der Großzügigkeit, bei der man gibt, obwohl man selbst bedürftig ist. Die Haltung der Anṣār."},
 {arab: "شُحّ", tr: "schuḥḥ", wurzel: "sch-ḥ-ḥ", erkl: "Gier, Geiz der Seele (59:9): „Wer vor der Gier seiner Seele bewahrt wird, das sind die Erfolgreichen.“ Schuḥḥ ist mehr als Geiz – es ist das Festhalten-Wollen tief in der Seele. Bewahrung davor ist Gnade."},
 {arab: "الْأَسْمَاء الْحُسْنَى", tr: "al-asmāʾ al-ḥusnā", wurzel: "s-m-w", erkl: "Die schönsten Namen (59:24) – die drei Schlussverse nennen siebzehn Namen Allahs: der König, der Heilige, der Friede, der Sicherheit Gebende, der Wächter, der Mächtige, der Gewaltige, der Stolze, der Schöpfer, der Erschaffer, der Gestalter … (vgl. 7:180, Lektion 39)."}
],
tafsir: [
 {vers: "Verse 1–5: Der Auszug", text: "„Allah preist, was in den Himmeln und auf der Erde ist.“ Dann: „Er ist es, der die Ungläubigen unter den Schriftbesitzern beim ersten Auszug aus ihren Häusern vertrieb. Ihr dachtet nicht, dass sie hinausgehen würden, und sie meinten, ihre Festungen würden sie vor Allah schützen. Da kam Allah über sie, von wo sie es nicht erwarteten, und warf Schrecken in ihre Herzen.“ Sie zerstörten ihre eigenen Häuser, um nichts zurückzulassen. „So zieht eine Lehre daraus, ihr Einsichtigen.“ Ibn Kathīr: Die Lehre ist allgemein – keine Festung, kein Bündnis, keine Macht schützt den, der Verträge bricht und Unrecht tut."},
 {vers: "Verse 6–10: Fayʾ und die drei Generationen", text: "Kampflose Beute gehört dem Gemeinwohl, „damit es nicht nur zwischen den Reichen unter euch umläuft. Und was der Gesandte euch gibt, das nehmt; und was er euch untersagt, dessen enthaltet euch.“ (59:7). Ibn Masʿūd nutzte diesen Satz als allgemeinen Beleg für die Autorität der Sunna (Sahih al-Buchari, Nr. 4886; Sahih Muslim, Nr. 2125). Dann drei Gruppen: die Muhādschirūn, die alles verließen (59:8); die Anṣār, die sie aufnahmen, „sie lieben die, die zu ihnen auswandern … und bevorzugen sie vor sich selbst, auch wenn sie selbst in Not sind“ (59:9); und die Späteren, die beten: „Unser Herr, vergib uns und unseren Brüdern, die uns im Glauben vorausgegangen sind, und lass in unseren Herzen keinen Groll gegen die Gläubigen“ (59:10). As-Saʿdī: Wer die Gefährten liebt und für sie betet, gehört zur dritten Gruppe dieser Sure."},
 {vers: "Verse 11–17: Die Heuchler und ihr Bündnis", text: "Die Heuchler Medinas hatten den Banū n-Naḍīr versprochen: „Wenn ihr vertrieben werdet, ziehen wir mit euch; wenn ihr bekämpft werdet, helfen wir euch.“ Allah bezeugt: „Sie lügen.“ Als es ernst wurde, hielt keiner Wort. Vers 14: „Ihre Gewalt untereinander ist heftig; du meinst, sie seien vereint, doch ihre Herzen sind gespalten.“ Vers 16 vergleicht sie mit dem Satan, der zum Menschen sagt: „Sei ungläubig!“ – und dann: „Ich sage mich los von dir.“ Al-Qurṭubī: Bündnisse auf Unrecht zerfallen, wenn es darauf ankommt."},
 {vers: "Verse 18–24: Morgen, der Berg und die Namen", text: "Vers 18: „Fürchtet Allah, und jede Seele schaue, was sie für morgen vorausschickt.“ – ‚Morgen‘ ist der Jüngste Tag, so nah wie der nächste Tag. Vers 19: „Seid nicht wie die, die Allah vergaßen, und Er ließ sie sich selbst vergessen.“ – Wer Allah vergisst, verliert am Ende sich selbst. Vers 21: „Würden Wir diesen Koran auf einen Berg herabsenden, du sähest ihn demütig, zerberstend aus Furcht vor Allah.“ Wenn ein Berg so reagieren würde – wie hart muss ein Herz sein, das ungerührt bleibt? (vgl. 57:16, Lektion 94). Dann die drei Verse der Namen: „Er ist Allah, außer Dem es keinen Gott gibt, der Kenner des Verborgenen und des Offenbaren … der König, der Heilige, der Friede … der Schöpfer, der Erschaffer, der Gestalter. Ihm gehören die schönsten Namen. Ihn preist, was in den Himmeln und auf der Erde ist.“ Die Sure endet, wie sie begann: mit dem Lobpreis der ganzen Schöpfung."}
],
ahadith: [
 {text: "Ibn ʿAbbās über Al-Ḥaschr: „Sag: Sure der Banū n-Naḍīr.“", quelle: "Sahih al-Buchari, Nr. 4882; Sahih Muslim, Nr. 3031"},
 {text: "Der Anṣārī, der mit seiner Frau das Licht löschte, damit ihr hungriger Gast satt wurde – „Allah hat gestaunt über das, was ihr beide getan habt“ – und 59:9 kam herab.", quelle: "Sahih al-Buchari, Nr. 3798; Sahih Muslim, Nr. 2054"},
 {text: "Ibn Masʿūd leitete aus „Was der Gesandte euch gibt, das nehmt“ (59:7) das Verbot bestimmter Körperveränderungen ab, die der Prophet ﷺ verboten hatte – als Beleg dafür, dass die Sunna Teil dessen ist, was ‚im Buch Allahs‘ steht.", quelle: "Sahih al-Buchari, Nr. 4886; Sahih Muslim, Nr. 2125"},
 {text: "„Hütet euch vor dem Geiz (schuḥḥ), denn der Geiz hat die vor euch zugrunde gerichtet.“ – zu 59:9.", quelle: "Sahih Muslim, Nr. 2578"}
],
hanafi: "Zu 59:7 („Was der Gesandte euch gibt, das nehmt“): Der Vers ist der Grundbeleg aller Schulen für die Verbindlichkeit der Sunna. Die hanafitische Rechtsmethodik (uṣūl) gewichtet dabei sorgfältig: Sie unterscheidet zwischen mutawātir-Überlieferungen (von so vielen überliefert, dass Irrtum ausgeschlossen ist), maschhūr-Überlieferungen (sehr verbreitet) und Einzelüberlieferungen (āḥād). Ein Koranvers mit klarer Bedeutung wird nach der Schule nicht durch eine Einzelüberlieferung eingeschränkt oder ergänzt – wohl aber durch eine mutawātir- oder maschhūr-Überlieferung. Das erklärt manche hanafitische Besonderheit (vgl. die Fātiḥa im Gebet als wādschib, nicht farḍ – Lektion 5). Kein Widerspruch zur Sunna, sondern eine Methode, ihre verschiedenen Gewissheitsstufen ernst zu nehmen.",
umsetzung: [
 "Mach 59:18 zur Abendfrage: „Was habe ich heute für morgen vorausgeschickt?“ – ein Satz, jeden Abend, ehrlich beantwortet.",
 "Übe īthār (59:9) einmal bewusst: Gib etwas, wenn du es selbst gerade brauchst – Zeit, Essen, Geld – und bitte Allah, dich vor schuḥḥ zu bewahren.",
 "Bete das Gebet aus 59:10 für die Gefährten und alle Gläubigen vor dir – und für dich, dass kein Groll gegen Gläubige in deinem Herzen bleibt.",
 "Lerne die Namen aus 59:22–24 auswendig – sie gehören zu den bekanntesten Koranversen, und viele rezitieren sie morgens und abends."
]
},

// ───────────────────────── Lektion 102: An-Nūr ─────────────────────────
{
sure: 24, offb: 102, name: "An-Nūr", arab: "سُورَةُ النُّورِ", de: "Das Licht", verse: 64, ort: "Medina",
zeit: "Medina, ca. 5/6 n. H. – nach dem Feldzug gegen die Banū l-Muṣṭaliq, als die Verleumdung gegen ʿĀʾischa die Gemeinde erschütterte",
kurz: "Eine Sure über den Schutz der Ehre – und über das Licht Allahs. Sie entstand aus einer Krise: Heuchler verbreiteten eine Verleumdung gegen ʿĀʾischa, die Frau des Propheten ﷺ, und einen Monat lang litt die ganze Gemeinde, bis Allah ihre Unschuld vom Himmel bezeugte. Die Sure regelt daraufhin, wie eine Gesellschaft Ehre schützt: hohe Strafe für Unzucht, aber noch höhere Hürden für den Beweis; Strafe für den, der keusche Frauen ohne vier Zeugen beschuldigt; Regeln für Blick, Kleidung, Besuch und Anklopfen. Mittendrin steht einer der schönsten Verse des ganzen Korans, der Lichtvers: „Allah ist das Licht der Himmel und der Erde.“ Die Botschaft: Eine Gesellschaft, die Ehre, Scham und Wahrheit schützt, wird vom Licht Allahs erhellt.",
schluessel: {arab: "اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ", ueb: "Allah ist das Licht der Himmel und der Erde.", ref: "24:35"},
kontext: ["Die Verleumdung (al-ifk): Auf dem Rückweg vom Feldzug gegen die Banū l-Muṣṭaliq suchte ʿĀʾischa eine verlorene Halskette; die Karawane zog ohne sie weiter, weil man sie in ihrer Sänfte glaubte. Ṣafwān ibn al-Muʿaṭṭal, der hinter dem Heer ging, fand sie und führte sie zurück. Der Anführer der Heuchler, ʿAbdullāh ibn Ubayy, machte daraus ein Gerücht, und einige Muslime trugen es weiter. ʿĀʾischa erzählt selbst die ganze Geschichte – einen Monat voller Schmerz, ihr Weinen, das Schweigen der Offenbarung, und die Verse, die ihre Unschuld bezeugten (Sahih al-Buchari, Nr. 4750; Sahih Muslim, Nr. 2770).",
"Ihre Antwort, als die Offenbarung kam und ihre Mutter sagte, sie solle sich beim Propheten ﷺ bedanken, gehört zu den stärksten Sätzen der Sīra: „Bei Allah, ich stehe nicht für ihn auf, und ich danke niemandem außer Allah.“ Ihre Unschuld war Allahs Werk, nicht das Werk der Menschen.",
"Die Sure ist Sozialgesetzgebung im besten Sinn: Sie schützt den Einzelnen vor öffentlicher Bloßstellung (Vier-Zeugen-Regel, Strafe für Verleumder), die Familie vor Eindringen (Anklopfen, Erlaubnis einholen), die Gesellschaft vor Unzucht (Blick senken, Kleidung, Ehe fördern). Die Brennpunkt-Verse 24:2 (Strafe für Unzucht) und 24:31 (Hidschāb) stehen hier – ausführlich mit Hukm im Brennpunkt-Modul."],
asbab: [
 {text: "24:11–26: die Verleumdung gegen ʿĀʾischa und die Offenbarung ihrer Unschuld.", quelle: "Sahih al-Buchari, Nr. 4750; Sahih Muslim, Nr. 2770"},
 {text: "24:6–9 (liʿān – gegenseitiger Fluchschwur der Ehepartner): Hilāl ibn Umayya bzw. ʿUwaimir al-ʿAdschlānī beschuldigten ihre Frauen, ohne vier Zeugen zu haben.", quelle: "Sahih al-Buchari, Nr. 4747 (Hilāl) und Nr. 5259 (ʿUwaimir); Sahih Muslim, Nr. 1492"},
 {text: "24:22: Abū Bakr wollte seinem Verwandten Misṭaḥ, der sich an der Verleumdung beteiligt hatte, die Unterstützung streichen. Der Vers kam herab: „Wollt ihr nicht, dass Allah euch vergibt?“ – „Doch, bei Allah“, sagte Abū Bakr, und gab ihm die Unterstützung zurück.", quelle: "Sahih al-Buchari, Nr. 4750 (im ifk-Bericht)"},
 {text: "24:33: ʿAbdullāh ibn Ubayy zwang seine Sklavinnen zur Prostitution; der Vers verbot es.", quelle: "Sahih Muslim, Nr. 3029"}
],
begriffe: [
 {arab: "الْإِفْك", tr: "al-ifk", wurzel: "ʾ-f-k", erkl: "Die ungeheuerliche Lüge, die Verleumdung – wörtlich ‚das Umgekehrte‘: eine Lüge, die die Wahrheit auf den Kopf stellt. Der Name der Affäre um ʿĀʾischa."},
 {arab: "الْمُحْصَنَات", tr: "al-muḥṣanāt", wurzel: "ḥ-ṣ-n", erkl: "Die keuschen Frauen – wörtlich ‚die Geschützten‘ (wie von einer Festung, ḥiṣn). Wer sie ohne vier Zeugen beschuldigt, wird bestraft (24:4) – ihre Ehre ist eine Festung, die das Recht schützt."},
 {arab: "لِعَان", tr: "liʿān", wurzel: "l-ʿ-n", erkl: "Der gegenseitige Fluchschwur der Ehepartner (24:6–9): Wenn ein Mann seiner Frau Untreue vorwirft, aber keine Zeugen hat, schwören beide viermal und rufen beim fünften Mal Allahs Fluch bzw. Zorn auf sich herab, falls sie lügen. Danach wird die Ehe getrennt."},
 {arab: "يَغُضُّوا مِنْ أَبْصَارِهِمْ", tr: "yaġuḍḍū min abṣārihim", wurzel: "ġ-ḍ-ḍ", erkl: "„Sie sollen ihre Blicke senken“ (24:30) – zuerst an die Männer gerichtet, dann an die Frauen (24:31). Der Schutz der Ehre beginnt beim Blick, nicht beim Tuch."},
 {arab: "خُمُر", tr: "chumur", wurzel: "ch-m-r", erkl: "Kopftücher – Plural von chimār, ‚das Bedeckende‘ (dieselbe Wurzel wie chamr, Wein, der den Verstand bedeckt). 24:31: Die Frauen sollen ihre Kopftücher über den Brustausschnitt ziehen. Siehe Brennpunkt 24:31."},
 {arab: "مِشْكَاة", tr: "mischkāt", wurzel: "–", erkl: "Die Nische (24:35) – im Lichtvers: eine Wandnische, darin eine Lampe, die Lampe in einem Glas, das Glas wie ein funkelnder Stern, entzündet von einem gesegneten Olivenbaum. „Licht über Licht.“"},
 {arab: "تَسْتَأْنِسُوا", tr: "tastaʾnisū", wurzel: "ʾ-n-s", erkl: "„Bis ihr um Erlaubnis bittet / vertraut seid“ (24:27) – betretet keine fremden Häuser, ohne euch bemerkbar zu machen und zu grüßen. Wörtlich: bis Vertrautheit (uns) hergestellt ist. Privatsphäre als koranisches Recht."}
],
tafsir: [
 {vers: "Verse 1–10: Unzucht, Verleumdung und Fluchschwur", text: "„Eine Sure, die Wir herabgesandt und verpflichtend gemacht haben.“ Vers 2: hundert Hiebe für Unzucht – mit der höchsten Beweishürde des gesamten Rechts (vier Augenzeugen oder freiwilliges, widerrufbares Geständnis; ausführlich im Brennpunkt 24:2). Vers 4: Wer keusche Frauen beschuldigt und keine vier Zeugen bringt, erhält achtzig Hiebe, sein Zeugnis wird nie wieder angenommen, „und das sind die Frevler“. Vers 5 öffnet die Tür der Reue. Die Verse 6–9 regeln den liʿān für Ehepartner. Ibn Kathīr: Die Sure schützt die Ehre so stark, dass nicht der Sünder im Verborgenen, sondern der Verleumder in der Öffentlichkeit zuerst bestraft wird."},
 {vers: "Verse 11–26: Die Verleumdung gegen ʿĀʾischa", text: "„Diejenigen, die die ungeheuerliche Lüge vorbrachten, sind eine Gruppe von euch. Haltet es nicht für ein Übel für euch – es ist gut für euch.“ – gut, weil daraus Recht für alle Zeiten entstand. Vers 12: „Warum dachten die gläubigen Männer und Frauen, als ihr es hörtet, nicht Gutes voneinander und sagten: Das ist eine offenkundige Lüge?“ Vers 15: „Ihr nahmt es mit euren Zungen auf und sagtet mit eurem Mund, wovon ihr kein Wissen hattet, und hieltet es für gering – bei Allah aber ist es gewaltig.“ Vers 19 warnt die, die gern sehen, dass sich Schändliches unter den Gläubigen verbreitet. Vers 22: Abū Bakr und Misṭaḥ – „Sie sollen verzeihen und nachsichtig sein. Wollt ihr nicht, dass Allah euch vergibt?“ Al-Qurṭubī: Diese Verse sind die stärkste Warnung des Korans gegen Gerüchte – sie gelten für jedes Weiterleiten ungeprüfter Vorwürfe, auch heute in sozialen Medien."},
 {vers: "Verse 27–34: Häuser, Blicke und Ehe", text: "Vers 27–29: Fremde Häuser nur mit Erlaubnis und Gruß betreten; wird man zurückgeschickt, geht man zurück. Vers 30: „Sag den gläubigen Männern, sie sollen ihre Blicke senken und ihre Scham hüten.“ Vers 31: dasselbe für die Frauen, dazu die Bedeckung: Schmuck nicht zeigen außer dem, was sichtbar ist, und das Kopftuch über den Brustausschnitt ziehen – mit der Liste der Personen, vor denen die Frau sich nicht bedecken muss (ausführlich im Brennpunkt 24:31). Vers 32: „Verheiratet die Ledigen unter euch … Wenn sie arm sind, wird Allah sie aus Seiner Huld reich machen.“ Vers 33: Wer nicht heiraten kann, soll keusch bleiben; Sklaven, die sich freikaufen wollen, soll man einen Freikaufvertrag gewähren und ihnen dabei helfen – und niemand darf seine Sklavinnen zur Prostitution zwingen."},
 {vers: "Verse 35–46: Der Lichtvers und die Häuser Allahs", text: "„Allah ist das Licht der Himmel und der Erde. Das Gleichnis Seines Lichts ist wie eine Nische, in der eine Lampe ist; die Lampe ist in einem Glas; das Glas ist, als wäre es ein funkelnder Stern, entzündet von einem gesegneten Baum, einem Ölbaum, weder östlich noch westlich, dessen Öl fast schon leuchtet, auch wenn es kein Feuer berührt hat – Licht über Licht. Allah leitet zu Seinem Licht, wen Er will.“ Ibn Kathīr nach Ubayy ibn Kaʿb: Die Nische ist die Brust des Gläubigen, die Lampe der Koran und der Glaube darin, das Glas sein Herz. Das Öl ist die fiṭra (vgl. 7:172, Lektion 39), die ‚fast schon leuchtet‘ – und der Koran entzündet sie: Licht (der Offenbarung) über Licht (der Natur). Vers 36–37: Dieses Licht ist in Häusern, die Allah zu errichten erlaubt hat – „Männer, die weder Handel noch Kauf vom Gedenken Allahs ablenkt“. Dagegen die Gleichnisse der Ungläubigen: eine Luftspiegelung in der Wüste (24:39) und Finsternisse übereinander in einem tiefen Meer – „wem Allah kein Licht gibt, der hat kein Licht“ (24:40)."},
 {vers: "Verse 47–57: Gehorsam und Verheißung", text: "Die Heuchler sagen „Wir glauben und gehorchen“ – aber wenn sie zu Allah und Seinem Gesandten gerufen werden, um zwischen ihnen zu richten, wenden sie sich ab, außer das Urteil ist zu ihren Gunsten (24:48–49). Die Gläubigen dagegen sagen: „Wir hören und gehorchen“ (24:51). Vers 55 ist eine große Verheißung: Allah hat denen, die glauben und Gutes tun, versprochen, sie zu Nachfolgern auf der Erde zu machen, ihre Religion zu festigen und ihre Angst in Sicherheit zu verwandeln – „sie dienen Mir und gesellen Mir nichts bei“. As-Saʿdī: Die Verheißung erfüllte sich in der Generation der Gefährten – und sie gilt für jede Generation, die die Bedingung erfüllt."},
 {vers: "Verse 58–64: Etikette in Haus und Gemeinschaft", text: "Drei Zeiten, zu denen auch Kinder und Bedienstete im Haus um Erlaubnis bitten müssen, bevor sie eintreten: vor dem Fadschr-Gebet, zur Mittagsruhe und nach dem ʿIschāʾ-Gebet – die Zeiten der Privatsphäre. Ältere Frauen, die keine Ehe mehr erwarten, dürfen ihre Überkleider ablegen, ohne Schmuck zur Schau zu stellen – „doch sich zurückzuhalten ist besser für sie“. Vers 61 erleichtert das gemeinsame Essen in Verwandtenhäusern und gebietet den Gruß beim Betreten: „ein Gruß von Allah, gesegnet und gut“. Die letzten Verse regeln den Umgang mit dem Propheten ﷺ in der Gemeinschaft: nicht ohne Erlaubnis weggehen, ihn nicht rufen, wie man einander ruft. Der Schlussvers: Allah weiß, in welchem Zustand ihr seid."}
],
ahadith: [
 {text: "ʿĀʾischas eigener ausführlicher Bericht über die Verleumdung, den Monat des Leidens und die Offenbarung ihrer Unschuld – „ich danke niemandem außer Allah“.", quelle: "Sahih al-Buchari, Nr. 4750; Sahih Muslim, Nr. 2770"},
 {text: "„Das Bitten um Erlaubnis (zum Eintreten) geschieht dreimal; wird dir erlaubt (gut), sonst kehre um.“ – zu 24:27–28.", quelle: "Sahih al-Buchari, Nr. 6245; Sahih Muslim, Nr. 2153"},
 {text: "Der Prophet ﷺ zu ʿAlī: „Lass dem Blick keinen zweiten Blick folgen; der erste gehört dir, der zweite nicht.“ – zu 24:30.", quelle: "Sunan Abū Dāwūd, Nr. 2149; at-Tirmidhī, Nr. 2777; hasan"},
 {text: "„Es genügt dem Menschen an Lüge, alles weiterzuerzählen, was er hört.“ – die Sunna-Lehre aus der ifk-Affäre.", quelle: "Sahih Muslim, Einleitung (Muqaddima; Zählung je nach Ausgabe verschieden); ebenso Sunan Abū Dāwūd, Nr. 4992 (sahih)"}
],
hanafi: "An-Nūr enthält zahlreiche Rechtsregeln, bei denen die hanafitische Schule eigene Positionen hat: (1) Verleumdung (qadhf, 24:4): Wer verurteilt wurde, dessen Zeugnis wird nach hanafitischer Schule NIE wieder angenommen, auch nicht nach Reue – die Ausnahme in Vers 5 („außer denen, die bereuen“) bezieht sich nach der Schule nur auf die Bezeichnung als ‚Frevler‘, nicht auf das Zeugnisverbot. Andere Schulen sehen das anders. (2) Liʿān (24:6–9): Nach Abū Ḥanīfa wird die Ehe nicht automatisch durch den Schwur getrennt, sondern durch das Urteil des Richters. (3) Unzucht (24:2): Schwangerschaft allein ist nach der Schule kein Beweis (vgl. Brennpunkt 24:2); die ḥadd-Strafe ist ausschließlich Sache eines islamischen Gerichts. (4) Bedeckung (24:31): Gesicht und Hände – nach der Schulmeinung auch die Füße – sind von der Bedeckungspflicht der Frau vor fremden Männern ausgenommen; in Zeiten verbreiteter Versuchung empfehlen spätere hanafitische Gelehrte das Bedecken des Gesichts. Der Mann soll seinen Blick senken – die Pflicht liegt zuerst bei ihm (24:30). (5) Anklopfen (24:27): Das Eintreten in fremde Wohnungen ohne Erlaubnis ist verboten, auch für Verwandte außerhalb des engsten Kreises.",
umsetzung: [
 "Wende 24:12 und 24:15 auf dein Handy an: Bevor du ein Gerücht, einen Screenshot oder einen Vorwurf weiterleitest, frag: Habe ich Wissen darüber – oder trage ich nur mit der Zunge weiter? Im Zweifel: Gutes denken und schweigen.",
 "Übe den Blick (24:30 + Abū Dāwūd 2149): Der erste Blick ist verzeihlich, der zweite nicht – trainiere eine Woche lang bewusst das sofortige Wegschauen.",
 "Lerne den Lichtvers (24:35) auswendig und denk beim Rezitieren an die Nische in deiner Brust: Ist die Lampe an?",
 "Respektiere Privatsphäre (24:27, 24:58): Klopf an, grüß, frag – auch bei Familienmitgliedern zu den drei Ruhezeiten. Und bring es deinen Kindern bei.",
 "Verzeihe wie Abū Bakr (24:22): Gibt es jemanden, der dir Unrecht getan hat und dem du deine Hilfe entzogen hast? „Wollt ihr nicht, dass Allah euch vergibt?“"
]
}
];
